({\bf Sufficient decrease inequality})\label{sufficient:lem}
Under \cref{ass_g_poi}~\ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2} and  \cref{ass_noise}~\ref{ass_noise:i}$\sim$ \ref{ass_noise:i2}, consider the sequence $\{\theta_{n}\}$ generated by AdaGrad-Norm, we have 
\begin{align}
\hat{g}(\theta_{n+1}) - \hat{g}(\theta_n) \leq -\frac{\alpha_{0}}{4}\zeta(n)+C_{\Gamma, 1}\cdot \Gamma_n  + C_{\Gamma, 2}\frac{\Gamma_n}{\sqrt{S_{n}}} + \alpha_0 \hat{X}_{n},
\end{align}
where $\hat{g}(\theta_{n}):=g(\theta_{n})+ \frac{\sigma_{0}\alpha_{0}}{2}\zeta(n)$, $\hat{X}_n = X_n + V_n$, and $V_n$ is defined in \cref{notation:Vn}. The constant terms $C_{\Gamma, 1}, C_{\Gamma, 2}$ are defined in \cref{notation:ghat:const}.

(of~\cref{sufficient:lem})
We first recall \cref{inequ:sufficient:decrease}
\begin{align}\label{adagrad:sufficient:inequ:1}
g(\theta_{n+1})-g(\theta_{n}) & \le - \alpha_{0}\zeta(n)+\alpha_{0}\mathbb{E}\left[R_n \Lambda_n \mid \mathscr{F}_{n-1}\right]+\frac{ L\alpha_{0}^{2}}{2}\Gamma_n +\alpha_0 X_{n} .
\end{align} 
Next, we focus on dealing with the second term on the RHS of \cref{adagrad:sufficient:inequ:1} and achieve:
\begin{align}\label{adagrad:sufficient:inequ:2}
& \mathbb{E}\left[R_n \Lambda_n \mid \mathscr{F}_{n-1}\right] := \frac{\|\nabla g(\theta_{n})\|}{\sqrt{S_{n-1}}}\cdot\mathbb{E}\left[\|\nabla g(\theta_{n},\xi_{n})\|\Lambda_n \mid \mathscr{F}_{n-1}\right]  \notag \\ \mathop{\le}^{(a)} &\frac{\|\nabla g(\theta_{n})\|^{2}}{2\sqrt{S_{n-1}}}+\frac{1}{2\sqrt{S_{n-1}}}\mathbb{E}^{2}\left[\|\nabla g(\theta_{n},\xi_{n})\| \Lambda_n \mid \mathscr{F}_{n-1}\right] \notag \\ \mathop{\le}^{(b)} &\frac{\zeta(n)}{2}+\frac{\mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\|^{2}|\mathscr{F}_{n-1}]}{2\sqrt{S_{n-1}}}\cdot\mathbb{E}\left[\Lambda_n^2 \mid \mathscr{F}_{n-1}\right] \notag \\ \mathop{\le}^{(c)}
&\frac{\zeta(n)}{2}+\frac{\sigma_{1}\mathbb{E}\left[\Lambda_n^2 \mid \mathscr{F}_{n-1}\right]}{2\sqrt{S_{n-1}}} +\frac{\sigma_{0}}{2}\cdot\frac{\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}\cdot \mathbb{E}\left[\Lambda_n^2 \mid \mathscr{F}_{n-1}\right] \notag \\
 \mathop{\le}^{(d)}
&\frac{\zeta(n)}{2}+\frac{\sigma_{1}}{2\sqrt{S_{0}}}\Gamma_n^2 +\frac{\sigma_{0}}{2}\cdot \zeta(n) \cdot \Lambda_n^2 +V_{n},
\end{align}
where for $(a), (b)$ we use \emph{Cauchy-Schwartz inequality}, $(c)$ is by applying the affine noise variance condition, and $(d)$ is by applying $\Lambda_n \leq \Gamma_n $  and $S_n \geq S_0$ for $(d)$. In the inequality, the martingale sequence $V_n$ is defined as
\begin{align}\label{notation:Vn}
&V_{n}:=\frac{\sigma_{1}}{2\sqrt{S_{0}}}\Big(\mathbb{E}\big[ \Gamma_n^2 \mid \mathscr{F}_{n-1}\big]- \Gamma_n^2 \Big)+\frac{\sigma_{0}}{2}\cdot\left(\mathbb{E}\left[\zeta(n)\cdot\Lambda_n^2 \mid \mathscr{F}_{n-1}\right]-\zeta(n) \cdot \Lambda_n^2\right).
\end{align}
We then substitute \cref{adagrad:sufficient:inequ:2} into \cref{adagrad:sufficient:inequ:1} and define $\hat{X}_{n}:=X_{n}+V_{n}$
\begin{align}
g(\theta_{n+1})-g(\theta_{n})  \le & - \frac{\alpha_{0}}{2} \zeta(n)+\frac{\alpha_{0}\sigma_{1}}{2\sqrt{S_{0}}}\cdot \Gamma_n^2 +\frac{\sigma_{0}\alpha_{0}}{2}\cdot \zeta(n)\cdot \Lambda_n^2 +\frac{ L\alpha_{0}^{2}}{2}\cdot  \Gamma_n\notag\\&+ \alpha_0 \hat{X}_{n}.
\end{align}
Recalling the definition of $\Lambda_n$ in ~\cref{inequ:sufficient:decrease} and applying $\Lambda_n \leq 1$ and \cref{inequ:sn:minus:sn1}, we have 
\begin{align}\label{inequ:cross:grad:lambda}
\zeta(n)\cdot \Lambda_n^2 & \leq   \frac{\|\nabla g(\theta_{n})\|^{2} \cdot \|\nabla g(\theta_{n}, \xi_n)\|^{2}}{\sqrt{S_{n-1}}\sqrt{S_{n}}(\sqrt{S_{n-1}} + \sqrt{S_n})} = \|\nabla g(\theta_{n})\|^{2} \left(\frac{1}{\sqrt{S_{n-1}}}-\frac{1}{\sqrt{S_{n}}} \right) \notag \\
& = \left(\frac{\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}-\frac{\|\nabla g(\theta_{n+1})\|^{2}}{\sqrt{S_{n}}}\right) + \frac{\|\nabla g(\theta_{n+1})\|^{2}-\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n}}}. 
\end{align}
By the smoothness of $g$, we estimate the last term of \cref{inequ:cross:grad:lambda}
\begin{align}\label{grad:norm:diff}
&\|\nabla g(\theta_{n+1})\|^{2}-\|\nabla g(\theta_{n})\|^{2} \notag \\
=&\ (2\|\nabla g(\theta_{n})\|+\|\nabla g(\theta_{n+1})\|-\|\nabla g(\theta_{n})\|)\cdot(\|\nabla g(\theta_{n+1})\|-\|\nabla g(\theta_{n})\|) \notag \\ \mathop{\leq}^{(a)} &\frac{2 L\alpha_{0}\|\nabla g(\theta_{n})\|\cdot\|\nabla g(\theta_{n},\xi_{n})\|}{\sqrt{S_{n}}}+\frac{\alpha_{0}^{2} L^{2}\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}} \notag \\
\mathop{\leq}^{(b)} &\frac{1}{2\sigma_0}\left\| \nabla g(\theta_{n})\right\|^2 + 2\sigma_0\alpha_0^2 L^2\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}} + \frac{\alpha_{0}^{2} L^{2}\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}},
\end{align}
where $(a)$ uses the smoothness of $g$ such that
\begin{align*}
\|\nabla g(\theta_{n+1})\|-\|\nabla g(\theta_{n})\| \leq \|\nabla g(\theta_{n+1}) - \nabla g(\theta_{n})\| = \alpha_0  L \frac{\left\|\nabla g(\theta_n, \xi_n) \right\|}{\sqrt{S_n}},
\end{align*}
and $(b)$ uses the Cauchy-Schwartz inequality.
Then applying \cref{grad:norm:diff} to \cref{inequ:cross:grad:lambda} yields
\begin{align*}
\zeta(n) \Lambda_n^2 & \leq  \frac{\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}-\frac{\|\nabla g(\theta_{n+1})\|^{2}}{\sqrt{S_{n}}} + \frac{\left\| \nabla g(\theta_{n})\right\|^2}{2\sigma_0} + \left( 2\sigma_0 + 1\right)\alpha_{0}^{2} L^{2}\frac{\Gamma_{n}}{\sqrt{S_{n}}}.
\end{align*}
Since $\Gamma_n \leq 1$, by applying the above estimation, the result can be formulated as
\begin{align*}
g(\theta_{n+1})-g(\theta_{n})  \le & -\frac{\alpha_{0}}{4}\zeta(n)+\left(\frac{\alpha_{0}\sigma_{1}}{2\sqrt{S_{0}}}  + \frac{ L\alpha_{0}^{2}}{2}\right)\cdot \Gamma_n  + \frac{\sigma_{0}\left( 2\sigma_0 + 1\right)\alpha_{0}^{3} L^{2}}{2}\frac{\Gamma_{n}}{\sqrt{S_{n}}} \notag \\
&+ \frac{\sigma_{0}\alpha_{0}}{2}\left(\zeta(n) - \zeta(n+1) \right) + \alpha_0 \hat{X}_{n}.
\end{align*}
We further introduce 
\begin{align}\label{notation:ghat:const}
\hat{g}(\theta_n) & = g(\theta_{n}) + \frac{\sigma_{0}\alpha_{0}}{2}\zeta(n), C_{\Gamma,1} = \left(\frac{\alpha_{0}\sigma_{1}}{2\sqrt{S_{0}}}  + \frac{ L\alpha_{0}^{2}}{2}\right);
C_{\Gamma,2}  = \frac{\sigma_{0}\left( 2\sigma_0 + 1\right)\alpha_{0}^{3} L^{2}}{2}
\end{align} to simplify this inequality, which rewrites the inequality to
\begin{align*}
\hat{g}(\theta_{n+1}) - \hat{g}(\theta_n) \leq -\frac{\alpha_{0}}{4}\zeta(n)+C_{\Gamma, 1}\cdot \Gamma_n  + C_{\Gamma, 2}\frac{\Gamma_n}{\sqrt{S_{n}}} + \alpha_0 \hat{X}_{n}.
\end{align*}

\label{stable}
