(of \cref{stable}) \\
\noindent{\bf Phase I:} To demonstrate the stability of the loss function sequence \(\{g(\theta_{n})\}_{n\ge 1}\), the key technique is to segment the entire iteration process according to the value of the Lyapunov function \(\hat{g}(\theta_{n})\). Specifically, we define the non-decreasing stopping times $\{\tau_{t}\}_{t\ge 1}$ as 
\begin{align}\label{stopping_time}
&\tau_{1}:=\min\{k\ge 1:\hat{g}(\theta_{k})>\Delta_0\},\ \tau_{2}:=\min\{k\ge \tau_{1}: \hat{g}(\theta_{k})\le  \Delta_0\ \text{or}\ \hat{g}(\theta_{k})>2\Delta_0\},\notag\\&\tau_{3}:=\min\{k\ge \tau_{2}:\hat{g}(\theta_{k})\le \Delta_0\},...,
\notag\\&\tau_{3i-2}:=\min\{k> \tau_{3i-3}:\hat{g}(\theta_{k})>\Delta_0\},\ \notag \\
&\tau_{3i-1}:=\min\{k\ge \tau_{3i-2}:\hat{g}(\theta_{k})\le  \Delta_0\ \text{or}\ \hat{g}(\theta_{k})>2\Delta_0\},\notag\\&\tau_{3i}:=\min\{k\ge  \tau_{3i-1}:\hat{g}(\theta_{k})\le  \Delta_0\}.
\end{align}
where $\Delta_0:=\max\{C_{0},\hat{C}_{g}\}$ and $C_0, \hat{C}_g$
are defined in \cref{lem:adj:ghat} and \cref{pro_0}, respectively.  
{For the first three stopping time $\tau_1, \tau_2, 
\tau_3$, we have $\tau_1 \leq \tau_2 \leq \tau_3$. When $\tau_1 = \tau_2$, we have $\hat{g}(\theta_{\tau_1}) > 2 \Delta_0$ while we have $\tau_2 < \tau_3$ such that $\hat{g}(\theta_{\tau_3}) \leq \Delta_0$ and $\hat{g}(\theta_n) > \Delta_0$ for $n \in [\tau_1, \tau_3)$. If $\tau_1 < \tau_2$ (that is $\Delta_0 < \hat{g}(\theta_{\tau_1}) < 2\Delta_0$), no matter $\tau_2 = \tau_3$ or $\tau_2 < \tau_3$, we have $\hat{g}(\theta_n) > \Delta_0$ for any $n \in [\tau_1, \tau_3)$. We thus conclude that $\hat{g}(\theta_n) > \Delta_0$ for any $n \in [\tau_{1}, \tau_3)$. }


Next, by the definition of the stopping times $\tau_{3i}$ and $\tau_{3i+1}$, $\forall\ n \in [\tau_{3i}, \tau_{3i+1})$ ($i \geq 1$), we have
\begin{align}\label{fab_2}
\hat{g}(\theta_{n}) \leq \Delta_0.\ \,\, 
\end{align}
Meanwhile, the stopping time $\tau_{3i-1} > \tau_{3i-2}$  holds for $i\ge 2$, because for any $\ i\ge 2$ we have
\[
\Delta_{0} < \hat{g}(\theta_{\tau_{3i-2}}) \le \hat{g}(\theta_{\tau_{3i-2}-1}) + h(\hat{g}(\theta_{\tau_{3i-2}-1})) \le \Delta_{0} + h(\Delta_{0}) \mathop{<}^{(a)} \frac{3\Delta_{0}}{2} < 2\Delta_{0},
\]
where $(a)$ is due to our choice of $\Delta_{0} > C_{0}$ such that $h(\Delta_{0}) < \frac{\Delta_{0}}{2}$ (\cref{lem:adj:ghat}). Combining with this result and the definition of the stopping times $\tau_{3i-1}$, we have for any $n \in [\tau_{3i-2}, \tau_{3i-1})\ (\forall\ i\ge 2)$
\begin{align}\label{fabulous}
g(\theta_{n}) < \hat{g}(\theta_{n}) < 2\Delta_{0}\quad  \text{and }  \quad \hat{g}(\theta_{n}) > \Delta_0.
\end{align}
Thus, the outliers only appear between the stopping times \([ \tau_{3i-1}, \tau_{3i})\). To demonstrate stability in \cref{stable}, we aim to prove that  for any \(T \geq 1\),   \(\mathbb{E}\left[\sup_{1 \le n <T} g(\theta_{n}) \right]\) has an finite upper bound that is independent of \(T\). By the \emph{Lebesgue's monotone convergence} theorem, \(\mathbb{E}\left[\sup_{n \ge 1} g(\theta_{n}) \right]\) is also controlled by this bound. 


\noindent{\bf Phase II:} In this step, for any $T \geq 1$, our aim is to estimate $\mathbb{E}[\sup_{1\le n<T}g(\theta_{n})]$ based on the segment of $g$ on the stopping time $\tau_t$ defined in the Phase I. For any $T \geq 1$, we define $\tau_{t,T} = \tau_t \wedge T$.
Specifically, we conclude the following auxiliary lemma, whose proof is provided in \cref{appendix:add:proof}.
\begin{lem}\label{lem:estimation:supg}
For the stopping time sequence defined in  \cref{stopping_time} and the intervals $I_{1,\tau}=[\tau_{1,T}, \tau_{3,T})$ and   $I_{i,\tau}^{'}=[\tau_{3i-1,T}, \tau_{3i,T})$, we have 
\begin{align}\label{lem:inequ:supg:main}
& \mathbb{E}\Big[\sup_{1\le n< T}g(\theta_{n})\Big] \notag \\
\le&\ \overline{C}_{\Pi,0}+ C_{\Pi,1}C_{\Delta_{0}}\cdot\sum_{i=2}^{+\infty}\underbrace{\mathbb{E}\big[\mathbb{I}_{\tau_{3i-1,T}<\tau_{3i,T}}\big]}_{\Psi_{i,1}}+C_{\Pi,1}C_{\Gamma,1}\underbrace{\mathbb{E}\left[\bigg(\sum_{I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\right]}_{\Psi_{2}} \notag \\&+C_{\Pi,1}C_{\Gamma,2}\underbrace{\mathbb{E}\Bigg[\bigg(\sum_{n=I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]}_{\Psi_{3}},
\end{align}
where $\overline{C}_{\Pi,0}:=\hat{g}(\theta_{1})+\frac{3\Delta_{0}}{2}+C_{\Pi,0}$,  $C_{\Pi,0},\ C_{\Pi,1}$ and $C_{\Delta_{0}}$ are constants defined in \cref{constant_Pi} and \cref{inequ:C:Delta0} respectively, and $C_{\Gamma,1}, C_{\Gamma,2}$ are constants defined in \cref{sufficient:lem}. 
\end{lem}

\noindent{\bf Phase III:} Next, we prove that the RHS of $\mathbb{E}\Big[\sup_{1\le n< T}g(\theta_{n})\Big]$ in \cref{lem:estimation:supg} is uniformly bounded for any \(T\). First, we introduce the following lemma, while the complete proof is provided in~\cref{appendix:add:proof}.
\begin{lem}\label{lem_su} 
Consider AdaGrad-Norm  and suppose that   \cref{ass_g_poi} \cref{ass_g_poi:i}$\sim$\cref{ass_g_poi:i2} and  \cref{ass_noise} \cref{ass_noise:i}$\sim$\cref{ass_noise:i2} hold. Then for any  $\nu>0$, 
\[
\mathbb{E}\Bigg[\sum_{n=1}^{+\infty}\mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\nu}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n-1}}\Bigg]<\Big({\sigma_{0}}+{\frac{\sigma_{1}}{{\nu}}}\Big)\cdot M<+\infty,\]
where $M$ is a constant that  depends only on the parameters $\theta_{1},$ $S_{0},$ $\alpha_{0}$, $\sigma_{0},$ $\sigma_{1},$ $ L.$
\end{lem}
Then, for the second term $\Psi_{2}$ of RHS of the result in \cref{lem:estimation:supg}, we have
\begin{align}\label{inequ:phi_2}
\Psi_{2} &= \mathbb{E}\Bigg[\bigg(\sum_{n=I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\Bigg] \notag \\
&\mathop{=}^{(a)} \mathbb{E}\Bigg[\bigg(\sum_{n=I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\eta}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}}\Bigg] \mathop{<}^{\text{\cref{lem_su}}}\Big({\sigma_{0}}+{\frac{\sigma_{1}}{{\eta}}}\Big)\cdot M,
\end{align}
where  $(a)$ is due to the fact that when the intervals $I_{1,\tau}=[\tau_{1,T}, \tau_{3,T})$ and   $I_{i,\tau}^{'}=[\tau_{3i-1,T}, \tau_{3i,T})$ are non-degenerated, we have $\hat{g}(\theta_{n}) > \Delta_0 \geq \hat{C}_{g}$,  which implies $\|\nabla g(\theta_{n})\|^{2} > \eta$ for any $ n \in I_{1,\tau}  \cup I_{i,\tau}^{'}$  (by \cref{pro_0}). 
For the last term \(\Psi_{3}\) of RHS of the result in \cref{lem:estimation:supg}, by using the series-integral comparison test, we have
\begin{align}\label{inequ:phi_3}
\Psi_{3} = \sum_{i=2}^{+\infty}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-1,T}}^{\tau_{3i,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]<\int_{S_{0}}^{+\infty}\frac{1}{x^{\frac{3}{2}}}\text{d}x<\frac{2}{\sqrt{S_{0}}}.
\end{align}
Then we will prove that there exists a uniform upper bound for $\Psi_{i,1}$ in the following lemma, which is the most challenging part of evaluating $\mathbb{E}\Big[\sup_{1\le n< T}g(\theta_{n})\Big]$ in \cref{lem:estimation:supg}.
\begin{lem}\label{lem:psi:i1}
We achieve the following upper bound for $\Psi_{i,1}$ defined in \cref{lem:inequ:supg:main}
\begin{align*} 

& \frac{4C_{\Gamma,1}}{\Delta_0}\cdot \mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\Bigg]  + \frac{4C_{\Gamma,2}}{\Delta_0}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg] + \frac{4\alpha_0^{2}}{\Delta_0^{2}}\mathbb{E} \left[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}^{2}\right].
\end{align*}
\end{lem}
Based on the estimation for the term $\Psi_{i,1}$ in \cref{lem:psi:i1}, we obtain an estimation for its sum
\begin{align}\label{power_01}
\sum_{i=2}^{+\infty}\Psi_{i,1} 
=&\sum_{i=2}^{+\infty}\mathbb{E}[\mathbb{I}_{\tau_{3i-1,T} < \tau_{3i,T}}]<\frac{4}{\Delta_0}C_{\Gamma,1}\cdot \sum_{i=2}^{+\infty}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\Bigg]\notag  \\&+ \frac{4C_{\Gamma,2}}{\Delta_0}\sum_{i=2}^{+\infty}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]  + \frac{4\alpha_0^{2}}{\Delta_0^{2}}\sum_{i=2}^{+\infty}\mathbb{E}\Bigg[ \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}^{2}\bigg].
\end{align}
First, we bound the first term on the RHS of \cref{power_01}. When the interval $[\tau_{3i-2,T}, \tau_{3i-1,T})$ is non-degenerated (i.e., $\tau_{3i-2} < \tau_{3i-1}$), we must have $\hat{g}(\theta_{n}) > \Delta_0 \geq \hat{C}_{g}$. By \cref{pro_0} we have $\|\nabla g(\theta_{n})\|^{2} > \eta$ for any $n \in [\tau_{3i-2,T}, \tau_{3i-1,T})$. Then, we obtain that
\begin{align}\label{jrnn_00}
\sum_{i=2}^{+\infty}\mathbb{E}\left[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}] \right]&=\sum_{i=2}^{+\infty}\mathbb{E}\left[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{E}\bigg[\mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\eta}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}}\bigg]\right]\notag\\& \mathop{<}^{\text{\cref{lem_su}}} \left(\sigma_0 + \frac{\sigma_1}{\eta} \right)M.
\end{align}
For the second term on the RHS of \cref{power_01}, by using the series-integral comparison test, we have:
\begin{align}\label{jrnn_01}
\sum_{i=2}^{+\infty}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]<\int_{S_{0}}^{+\infty}\frac{1}{x^{\frac{3}{2}}}\text{d}x<\frac{2}{\sqrt{S_{0}}}.
\end{align}
For the third term of \cref{power_01}, we have:
\begin{align}\label{jrnn_02}
& \sum_{i=2}^{+\infty}\mathbb{E}\left[ \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}^{2}\right] \le 2\sum_{i=2}^{+\infty}\mathbb{E}\left[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}(X_{n}^{2}+V_{n}^{2})\right]\notag\\& \le\ 2\sum_{i=2}^{+\infty}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\|\nabla g(\theta_{n})\|^{2}\Gamma_{n}+\bigg(\frac{\sigma_{1}}{2\sqrt{S_{0}}}\Gamma^{2}_{n}+\frac{\sigma_{0}}{2}\Lambda_{n}^{2}\bigg)^{2}\Bigg]\notag\\ & \mathop{\leq}^{(a)}\ 2\Big(4{ L\Delta_0}+\frac{\sigma_{1}}{2\sqrt{S_{0}}}+\frac{\sigma_{0}}{8}\Big)\sum_{i=2}^{+\infty}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\Gamma_{n}\Bigg]\notag\\ &\mathop{=}^{(b)}\ 2\Big(4{ L\Delta_0}+\frac{\sigma_{1}}{2\sqrt{S_{0}}}+\frac{\sigma_{0}}{8}\Big)\sum_{i=2}^{+\infty}\mathbb{E}\bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\eta}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{{S_{n}}} \bigg]\notag\\
& \leq \ 2\Big(4{ L\Delta_0}+\frac{\sigma_{1}}{2\sqrt{S_{0}}}+\frac{\sigma_{0}}{8}\Big)\sum_{i=2}^{+\infty}\mathbb{E}\bigg[\sum _{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\eta}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{{S_{n-1}}} \bigg]\notag\\
&\mathop{<}^{\text{\cref{lem_su}}}\ 2\Big(4{ L\Delta_0}+\frac{\sigma_{1}}{2\sqrt{S_{0}}}+\frac{\sigma_{0}}{8}\Big) \left(\sigma_0 + \frac{\sigma_1}{\eta} \right)M,
\end{align}
where $(a)$ is due to when $n\in[\tau_{3i-2,T},\tau_{3i-1,T}),$ there is $\|\nabla g(\theta_{n})\|^{2} \leq 2 Lg(\theta_n) \leq  {4 L\Delta_0},$ and $\Lambda_{n}\le \frac{1}{2}\Gamma_{n}$; $(b)$ is because when the interval $[\tau_{3i-2,T}, \tau_{3i-1,T})$ is non-degenerated (i.e., $\tau_{3i-2} < \tau_{3i-1}$), we have $\hat{g}(\theta_{n}) > \Delta_0 \geq \hat{C}_{g}$. By \cref{pro_0} we have $\|\nabla g(\theta_{n})\|^{2} > \eta$ for any $n \in [\tau_{3i-2,T}, \tau_{3i-1,T})$. Substituting \cref{jrnn_00}, \cref{jrnn_01}, and \cref{jrnn_02} into \cref{power_01} yields
\begin{equation}\nonumber\begin{aligned}
\sum_{i=2}^{+\infty}\Psi_{i,1}&< \frac{4C_{\Gamma,1}}{\Delta_0}\left(\sigma_0 + \sigma_1/\eta \right) M + \frac{4C_{\Gamma,2}}{\Delta_0}\frac{2}{\sqrt{S_0}}\\& + \frac{4\alpha_0^2}{\Delta_0^2} 2\left(4 L\Delta_0+\frac{\sigma_{1}}{2\sqrt{S_{0}}}+\frac{\sigma_{0}}{8}\right) \left(\sigma_0 + \frac{\sigma_1}{\eta} \right)M :=\overline{M},
\end{aligned}\end{equation}
which means there exists a constant $\overline{M} < +\infty$ such that $\sum_{i=2}^{+\infty}\Psi_{i,1}<\overline{M}$.
Combining the above estimation of $\sum_{i=2}^{+\infty}\Psi_{i,1}$ and estimations of $\Psi_2$ and $\Psi_3$ in \cref{inequ:phi_2,inequ:phi_3} into \cref{lem:inequ:supg:main}, we have 
\begin{equation}\nonumber\begin{aligned}
\mathbb{E}\Big[\sup_{1\le n<T}g(\theta_{n})\Big]&< \overline{C}_{\Pi,0} + C_{\Pi,1}C_{\Delta_0} \overline{M} + C_{\Pi,1}C_{\Gamma,1}\left(\sigma_0 + \frac{\sigma_1}{\eta} \right)M + C_{\Pi,1}C_{\Gamma,2} \frac{2}{\sqrt{S_0}}\\&:=\overline{M}_{1}<+\infty.
\end{aligned}\end{equation}
Therefore, there exists a constant $\overline{M}_{1} < +\infty$ that is independent on $T$ such that $\mathbb{E}\Big[\sup_{1\le n<T}g(\theta_{n})\Big]<+\infty$.
Since \(\overline{M}_{1}\) is independent of \(T\), according to the \emph{ Lebesgue's monotone convergence} theorem, we have $\mathbb{E}\Big[\sup_{n\ge 1}g(\theta_{n})\Big]<\overline{M}_{1}<+\infty,$ as we desired.

\label{lem:estimation:supg}
For the stopping time sequence defined in  \cref{stopping_time} and the intervals $I_{1,\tau}=[\tau_{1,T}, \tau_{3,T})$ and   $I_{i,\tau}^{'}=[\tau_{3i-1,T}, \tau_{3i,T})$, we have 
\begin{align}\label{lem:inequ:supg:main}
& \mathbb{E}\Big[\sup_{1\le n< T}g(\theta_{n})\Big] \notag \\
\le&\ \overline{C}_{\Pi,0}+ C_{\Pi,1}C_{\Delta_{0}}\cdot\sum_{i=2}^{+\infty}\underbrace{\mathbb{E}\big[\mathbb{I}_{\tau_{3i-1,T}<\tau_{3i,T}}\big]}_{\Psi_{i,1}}+C_{\Pi,1}C_{\Gamma,1}\underbrace{\mathbb{E}\left[\bigg(\sum_{I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\right]}_{\Psi_{2}} \notag \\&+C_{\Pi,1}C_{\Gamma,2}\underbrace{\mathbb{E}\Bigg[\bigg(\sum_{n=I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]}_{\Psi_{3}},
\end{align}
where $\overline{C}_{\Pi,0}:=\hat{g}(\theta_{1})+\frac{3\Delta_{0}}{2}+C_{\Pi,0}$,  $C_{\Pi,0},\ C_{\Pi,1}$ and $C_{\Delta_{0}}$ are constants defined in \cref{constant_Pi} and \cref{inequ:C:Delta0} respectively, and $C_{\Gamma,1}, C_{\Gamma,2}$ are constants defined in \cref{sufficient:lem}.

\label{lem:psi:i1}
We achieve the following upper bound for $\Psi_{i,1}$ defined in \cref{lem:inequ:supg:main}
\begin{align*} 

& \frac{4C_{\Gamma,1}}{\Delta_0}\cdot \mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\Bigg]  + \frac{4C_{\Gamma,2}}{\Delta_0}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg] + \frac{4\alpha_0^{2}}{\Delta_0^{2}}\mathbb{E} \left[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}^{2}\right].
\end{align*}

\label{extra}
\begin{enumerate}[label=\textnormal{(\roman*)}, leftmargin=*]
\item\label{extra:i1} (\textbf{Coercivity}) The function $g$ is coercive, that is, $\lim_{\|\theta\|\rightarrow+\infty} g(\theta) = +\infty$.
\item\label{extra:i2} (\textbf{Weak Sard Condition}) The critical value set $\{g(\theta) \mid \nabla g(\theta) = 0\}$ is nowhere dense in $\mathbb{R}$.
\end{enumerate}

\label{stable':iterate}
If \cref{ass_g_poi,ass_noise} and \cref{extra}~\ref{extra:i1} hold, given AdaGrad-Norm, we have
$$\sup_{n\ge 1}\|\theta_{n}\|<+\infty\ \ \text{a.s.}$$

\label{convergence_1} 
Consider the AdaGrad-Norm algorithm defined in \cref{AdaGrad_Norm}. If \cref{ass_g_poi,ass_noise,extra} hold, then for any initial point $\theta_{1}\in \mathbb{R}^{d}$ and $S_{0}>0,$ we have
\begin{equation}\nonumber\begin{aligned}
\lim_{n\rightarrow\infty}\|\nabla g(\theta_{n})\|=0\ \ \text{a.s.}
\end{aligned}\end{equation}

\label{convergence_2}
Consider the AdaGrad-Norm algorithm shown in  \cref{AdaGrad_Norm}. If \cref{ass_g_poi,ass_noise,extra} hold, then for any initial point $ \theta_{1}\in \mathbb{R}^{d}$ and $S_{0}>0,$  we have
\begin{equation}\nonumber\begin{aligned}
\lim_{n\rightarrow\infty}\mathbb{E}\|\nabla g(\theta_{n})\|^{2}=0.
\end{aligned}\end{equation}

\label{lem8}
Under \cref{ass_g_poi}~\ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2} and  \cref{ass_noise}~\ref{ass_noise:i}$\sim$ \ref{ass_noise:i2}, for the AdaGrad-Norm algorithm we have
\begin{equation}\nonumber\begin{aligned}
\sum_{n=1}^{T}\mathbb{E}\bigg[\frac{\big\|\nabla g(\theta_{n})\big\|^{2}}{\sqrt{S_{n-1}}}\bigg] \leq \mathcal{O}(\ln T).
\end{aligned}\end{equation}

\label{lem23} 
Under \cref{ass_g_poi}~\ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2} and  \cref{ass_noise}~\ref{ass_noise:i}$\sim$ \ref{ass_noise:i2}, for the AdaGrad-Norm algorithm we have
\begin{equation}\label{adagrad:123321}\begin{aligned}
\sum_{n=1}^{T}\mathbb{E}\Bigg[\frac{g(\theta_{n})\cdot\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}\Bigg]=\mathcal{O}(\ln^{2} T).
\end{aligned}\end{equation}

\label{lem:st}
Consider AdaGrad-Norm in \cref{AdaGrad_Norm} and suppose that   \cref{ass_g_poi}~\ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2} and  \cref{ass_noise}~\ref{ass_noise:i}$\sim$ \ref{ass_noise:i2} hold, then for any initial point $\theta_{1}\in \mathbb{R}^{d}$ and $S_{0}>0,$  we have
\begin{align}
\mathbb{E}[S_T] = \mathcal{O}\left(T\right).
\end{align}

Recall the sufficient decrease inequality in \cref{sufficient:lem} and telescope the indices \( n \) from 1 to \( T \). We obtain
\begin{align}\label{inequ:ST:decrease}
\frac{\alpha_{0}}{4}\cdot\sum_{n=1}^{T}\zeta(n) \le&\ \hat{g}(\theta_{1})+\Big(\frac{\alpha_{0}\sigma_{1}}{2\sqrt{S_{0}}}+\frac{ L\alpha_{0}^{2}}{2}\Big)\cdot\sum_{n=1}^{T}\Gamma_n   \notag \\&+\Big( L^{2}\alpha_{0}^{3}\sigma_{0}^{2}+\frac{ L^{2}\alpha_{0}^{3}\sigma_{0}}{2}\Big)\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}^{\frac{3}{2}}} +\alpha_0\sum_{n=1}^{T}\hat{X}_{n}.
\end{align}
Note that $S_T \geq S_{n-1}$ for all $n \geq [1, T]$. We have
\begin{align}\label{inequ:sum:grad:sn:1}
&\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{T}}} \leq \sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}} ,\notag \\& \sum_{n=1}^{T} \Gamma_n  =  \sum_{n=1}^{T} \frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}} \leq \int_{S_{0}}^{S_{T}}\frac{1}{x}\text{d}x \leq \ln (S_T/S_0), \notag \\&\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S^{\frac{3}{2}}_{n}}  \leq \int_{S_{0}}^{+\infty}\frac{1}{x^{\frac{3}{2}}}=\frac{2}{\sqrt{S_{0}}}.
\end{align}
Applying the above results and dividing $\alpha_0/(4\sqrt{S_T})$ over \cref{inequ:ST:decrease} and taking the mathematical expectation on both sides of the above inequality  give
\begin{align}\label{inequ:norm:grad:sum}
\sum_{n=1}^{T}\mathbb{E}\|\nabla g(\theta_{n})\|^{2}&\le \bigg(\frac{4g(\theta_{1})}{\alpha_0}+\frac{2\sigma_{0}\|\nabla g(\theta_{1})\|^{2}}{\sqrt{S_{0}}}+\frac{4 L^{2}\alpha_{0}^{2}\sigma_{0}}{\sqrt{S_{0}}}\Big(2\sigma_{0}+1\Big) - \ln(S_0)\bigg)\mathbb{E}\left(\sqrt{S_{T}} \right)\notag \\& +2\Big(\frac{\sigma_{1}}{\sqrt{S_{0}}}+ L\alpha_{0}\Big)\cdot \mathbb{E}\left(\sqrt{S_{T}}\ln (S_{T})\right)+ 4\mathbb{E}\bigg[\sqrt{S_{T}}\cdot\sum_{n=1}^{T}\hat{X}_{n}\bigg].
\end{align}
Because $f_1(x)=\sqrt{x}, f_2(x)=\sqrt{x}\ln(x)$ are concave functions, by \emph{Jensen's inequality}, we have 
\begin{align}
&\mathbb{E}\left(\sqrt{S_T} \right) \leq \sqrt{\mathbb{E}\left(S_T \right)}, \quad \mathbb{E}\left(\sqrt{S_T}\ln(S_T) \right) \leq \sqrt{\mathbb{E}\left(S_T \right)} \ln(\mathbb{E}(S_T)),  \label{inequ:ST}\\
& \mathbb{E}\bigg[\sqrt{S_{T}}\cdot\sum_{n=1}^{T}\hat{X}_{n}\bigg] \mathop{\leq}^{(a)}   \sqrt{\mathbb{E}[S_{T}]\cdot\mathbb{E}\bigg[\sum_{n=1}^{T}\hat{X}_{n}\bigg]^{2}},\label{inequ:ST:M'n}
\end{align}
where $(a)$ follows from  \emph{Cauchy Schwartz inequality} for expectation $\mathbb{E}(XY)^2 \leq \mathbb{E}(X^2)\mathbb{E}(Y^2)$. Applying the above estimations in \cref{inequ:ST} and \cref{inequ:ST:M'n} into \cref{inequ:norm:grad:sum}, we have
\begin{equation}\label{zxc_t54}\begin{aligned}
\sum_{n=1}^{T}\mathbb{E}\|\nabla g(\theta_{n})\|^{2}&\le C_1 \sqrt{\mathbb{E}\left(S_T \right)} + C_2\sqrt{\mathbb{E}\left(S_T \right)} \ln(\mathbb{E}(S_T)) +\sqrt{\mathbb{E}[S_{T}]\cdot\mathbb{E}\bigg[\sum_{n=1}^{T}\hat{X}_{n}\bigg]^{2}},
\end{aligned}\end{equation}
where $C_1 = \frac{4g(\theta_{1})}{\alpha_0}+\frac{2\sigma_{0}\|\nabla g(\theta_{1})\|^{2}}{\sqrt{S_{0}}}+\frac{4 L^{2}\alpha_{0}^{2}\sigma_{0}}{\sqrt{S_{0}}}\Big(2\sigma_{0}+1\Big) - \ln(S_0)$ and $C_2 = 2\Big(\frac{\sigma_{1}}{\sqrt{S_{0}}}+ L\alpha_{0}\Big)$. 


Now we estimate the term \(\mathbb{E}\big[\sum_{n=1}^{T}\hat{X}_{n}\big]^{2}\) in \cref{zxc_t54}. Since  $\left\lbrace \hat{X}_{n},\mathscr{F}_{n}\right\rbrace_{n}^{+\infty}$ is a martingale difference sequence, that is $\forall\ T\ge 1,$ there is
$\mathbb{E}\bigg[\sum_{n=1}^{T}\hat{X}_{n}\bigg]^{2}=\sum_{n=1}^{T}\mathbb{E}[\hat{X}_{n}]^{2},$ by recalling the definition of $\hat{X}_{n}$ in \cref{sufficient:lem}, we have
\begin{equation}\nonumber\begin{aligned}
\sum_{n=1}^{T}\mathbb{E}[\hat{X}_{n}]^{2} \leq&\ 2 \sum_{n=1}^{T}\mathbb{E} X_{n}^{2} + 2 \sum_{n=1}^{T}\mathbb{E} V_{n}^{2} \notag \\
\le&\ 2\sum_{n=1}^{T}\mathbb{E}\bigg[\frac{\|\nabla g(\theta_{n})\|^{2}\cdot\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}}\bigg]+\frac{2\alpha_{0}^{2}\sigma_{1}^{2}}{4S_{0}}\sum_{n=1}^{T}\mathbb{E}\bigg[\Gamma_n^4\bigg]\notag\\& + \frac{\sigma_0^2}{2}\sum_{n=1}^{T}\mathbb{E}\left[\zeta(n)^2 \Lambda_n^4\right]\\
\mathop{\leq}^{(a)} &\ 2\sum_{n=1}^{T}\mathbb{E}\bigg[\frac{\|\nabla g(\theta_{n})\|^{2}\cdot\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n-1}}\bigg]+\frac{\alpha_{0}^{2}\sigma_{1}^{2}}{2S_{0}}\sum_{n=1}^{T}\mathbb{E}\bigg[\Gamma_n\bigg]\notag\\& + \frac{\sigma_0^2}{2}\sum_{n=1}^{T}\mathbb{E}\left[\zeta(n)^2\right]   \notag \\
\mathop{\le}^{(b)} &\ 2\sigma_{1}\sum_{n=1}^{T}\mathbb{E}\bigg[\frac{\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\bigg]+4\sigma_{0} L\sum_{n=1}^{T}\mathbb{E}\left(\frac{g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\right)\notag\\&+\frac{\alpha_{0}^{2}\sigma_{1}^{2}}{2S_{0}}\mathbb{E}[\ln( S_{T} / S_0)]  + \sigma_0^2 L\sum_{n=1}^{T}\mathbb{E}\left(\frac{g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\right) ,
\end{aligned}\end{equation}
where $(a)$ follows from the fact that $S_n \geq S_{n-1}$ and $\Lambda_n \leq \Gamma_n  \leq 1$, $(b)$ uses the affine noise variance condition of $\nabla g(\theta_{n},\xi_{n})$ and \cref{loss_bound}, i.e.
\[\mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\|^{2}|\mathscr{F}_{n-1}]\le \sigma_{0}\|\nabla g(\theta_{n})\|^{2}+\sigma_{1}\ \text{and}\ \|\nabla g(\theta_{n})\|^{2}\le 2 Lg(\theta_{n})\ (\text{\cref{loss_bound}}),\]
and the last two terms can be estimated as
\begin{align}
\sum_{n=1}^{T}\mathbb{E}\bigg[\Gamma_n\bigg] &  = \mathbb{E} \left[\sum_{n=1}^{T} \frac{\left\|\nabla g(\theta_n; \xi_n)\right\|^2}{S_n}\right] = \mathbb{E} \left[\int_{S_0}^{S_T} \frac{dx}{x} \right] = \mathbb{E} \left[\ln(S_T/S_0) \right] \\&\leq \ln \mathbb{E}\left[S_T\right]- \ln(S_0), \notag \\
\mathbb{E}\left[\zeta(n)^2\right]  &  = \mathbb{E} \left[\frac{\left\|\nabla g(\theta_n)\right\|^4}{S_{n-1}}\right] \leq 2 L\mathbb{E}\left[\frac{g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\right].
\end{align}
Applying \cref{lem8} and \cref{lem23}, we have
\[\sum_{n=1}^{T}\bigg(\frac{\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\bigg)\le \frac{1}{\sqrt{S_{0}}}\sum_{n=1}^{T}\bigg(\frac{\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}\bigg)=\mathcal{O}(\ln T),\]\[ \sum_{n=1}^{T}\bigg(\frac{g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\bigg)\le \frac{1}{\sqrt{S_{0}}}\sum_{n=1}^{T}\bigg(\frac{g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}\bigg)=\mathcal{O}(\ln^{2} T),\] which induces that
\begin{equation}\nonumber\begin{aligned}
\sum_{n=1}^{T}\mathbb{E}[\hat{X}_{n}]^{2}\le \frac{\alpha_{0}^{2}\sigma_{1}^{2}}{2S_{0}}\ln\mathbb{E}[S_{T}]+\mathcal{O}(\ln^{2}T).
\end{aligned}\end{equation}
Substituting the above estimation of $\sum_{n=1}^{T}\mathbb{E}[\hat{X}_{n}]^{2}$ into \cref{zxc_t54}, we have
\begin{equation}\label{zxc_t54'}\begin{aligned}
\sum_{n=1}^{T}\mathbb{E}\|\nabla g(\theta_{n})\|^{2}&\le C_1\sqrt{\mathbb{E}{S_{T}}}+ \left(C_2 + \frac{\alpha_0\sigma_1}{\sqrt{2S_0}}\right)\sqrt{\mathbb{E}[S_{T}]\cdot \ln \mathbb{E}[S_{T}]}+\mathcal{O}({\ln T})\cdot\sqrt{\mathbb{E} S_{T}}.
\end{aligned}\end{equation} 
Note that by the affine noise variance condition, we have 
\begin{align*}
\mathbb{E}(S_T - S_0)=\mathbb{E}\left[\sum_{n=1}^{T}\left\|\nabla g(\theta_n,\xi_n) \right\|^2\right]= \sum_{n=1}^{T}\mathbb{E}\left[\left\|\nabla g(\theta_n,\xi_n) \right\|^2\right] \leq \sigma_0\sum_{n=1}^{T} \mathbb{E}\left[\left\|\nabla g(\theta_n) \right\|^2\right] + \sigma_1 T, 
\end{align*} 
that is 
\[\sum_{n=1}^{T}\mathbb{E}\|\nabla g(\theta_{n})\|^{2}\ge \frac{1}{\sigma_{0}}\mathbb{E}[S_{T}]-\frac{\sigma_{1}}{\sigma_{0}}T-\frac{S_{0}}{\sigma_{0}}.\]
Combing the inequality with \cref{zxc_t54'} gives
\begin{equation}\nonumber\begin{aligned}
\mathbb{E}[S_{T}]\le \sigma_0C_1\sqrt{\mathbb{E}{S_{T}}}+ \sigma_0\left(C_2 + \frac{\alpha_0\sigma_1}{\sqrt{2S_0}}\right)\sqrt{\mathbb{E}[S_{T}]\cdot \ln \mathbb{E}[S_{T}]}+\mathcal{O}({\ln T})\cdot\sqrt{\mathbb{E} S_{T}}+ \sigma_1 T.
\end{aligned}\end{equation}
By treating $\mathbb{E}[S_T]$ as the variable of a function, to estimate $\mathbb{E}[S_T]$ is equivalent to solve
\begin{align}
x \leq \sigma_0C_1\sqrt{x}+ \sigma_0\left(C_2 + \frac{\alpha_0\sigma_1}{\sqrt{2S_0}}\right)\sqrt{x\cdot \ln(x)}+\mathcal{O}({\ln T})\cdot\sqrt{x}+ \sigma_1 T
\end{align}
for any $T \geq 1$. This concludes  
$$\mathbb{E}[S_{T}] \leq \mathcal{O}(T), $$ 
where the hidden term of $\mathcal{O}$  depends only on $\theta_{1}$, $S_{0}$, $\alpha_{0}$, $ L$,$\sigma_{0},$ and $\sigma_{1}.$

\label{convergence_rate_0}
Under \cref{ass_g_poi}~\ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2} and  \cref{ass_noise}~\ref{ass_noise:i}$\sim$ \ref{ass_noise:i2}, consider the sequence $\{\theta_{n}\}$ generated by AdaGrad-Norm. For any $\theta_{1}\in \mathbb{R}^{d}$ and $S_{0}>0,$ we have
$$\frac{1}{T}\sum_{n=1}^{T}{\mathbb{E}\big\|\nabla g(\theta_{n})\big\|^{2}} \leq \mathcal{O}\bigg(\frac{\ln T}{\sqrt{T}}\bigg),\ \ \text{and}\ \ \min_{1\le n\le T}\mathbb{E}\big[\|\nabla g(\theta_{n})\|^{2}\big] \leq \mathcal{O}\bigg(\frac{\ln T}{\sqrt{T}}\bigg).$$

By applying the estimation of $\mathbb{E}(S_T)$ in \cref{lem:st} to \cref{zxc_t54'}, we have
\begin{align*}
\frac{1}{T}\sum_{n=1}^{T}\mathbb{E}\|\nabla g(\theta_{n})\|^{2}&\le \frac{C_1\sqrt{\sigma_1}}{\sqrt{T}} + \left(C_2 + \frac{\alpha_0\sigma_1}{\sqrt{2S_0}}\right)\frac{\sqrt{\sigma_1}\sqrt{\ln(T)}}{\sqrt{T}}+\frac{\mathcal{O}({\ln T})\sqrt{\sigma_1}}{\sqrt{T}}. 
\end{align*}

\label{coro:rate}
Under \cref{ass_g_poi}~\ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2} and  \cref{ass_noise}~\ref{ass_noise:i}$\sim$ \ref{ass_noise:i2}, consider the sequence $\{\theta_{n}\}$ generated by AdaGrad-Norm. For any initial point $\theta_{1}\in \mathbb{R}^{d}$ and $S_{0}>0,$ we have with probability at least $1-\delta,$
$$\frac{1}{T}\sum_{k=1}^{T}{\big\|\nabla g(\theta_{n})\big\|^{2}} \leq \mathcal{O}\bigg(\frac{1}{\delta}\cdot\frac{\ln T}{\sqrt{T}}\bigg),\ \ \text{and}\ \min_{1\le k\le n}\|\nabla g(\theta_{n})\|^{2} \leq \mathcal{O}\bigg(\frac{1}{\delta}\cdot\frac{\ln T}{\sqrt{T}}\bigg).$$

\label{coordinate}
The stochastic gradient $\nabla g(\theta_n, \xi_n)$ satisfies 
\begin{enumerate}[label=\textnormal{(\roman*)},leftmargin=*]
\item\label{coordinate_i_1}  
Each coordinate of $\nabla g(\theta_{n},\xi_{n})$  satisfies that \(\mathbb{E}[\nabla g_{i}(\theta_{n},\xi_{n})^{2} \mid \mathscr{F}_{n-1}]  \leq \sigma_{0}(\nabla g_{i}(\theta_{n}))^{2} + \sigma_{1}.\)
 \item\label{coordinate_i_2}  For any $i\in[d],$ any $\theta_n$ satisfying $(\nabla_{i} g(\theta_{n}))^{2}<D_{0}$, we have $(\nabla_{i} g(\theta_{n},\xi_{n}))^{2}<D_{1}\ \ \text{a.s.}$ for some constants $D_0, D_1 >0$.
\end{enumerate}

\label{sufficient:lem'}
Under \cref{ass_g_poi} \ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2}, \cref{ass_noise} \ref{ass_noise:i}, \cref{coordinate} \ref{coordinate_i_1}, consider the sequence $\{\theta_{t}\}$ generated by RMSProp, we have the following sufficient decrease inequality. 
\begin{align}\label{jh_30}
\hat{g}(\theta_{t+1})-\hat{g}(\theta_t) & \le-\frac{3}{4}\sum_{i=1}^{d}\zeta_{i}(t)+\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\|\eta_{t}\circ \nabla g(\theta_{t},\xi_{t})\|^{2}+M_{t},
\end{align} 
where $M_{t}:=M_{t,1}+M_{t,2}+M_{t,3}$ is a martingale difference sequence with \( M_{t,1} \) defined in \cref{adam_0} and \( M_{t,2} \), \( M_{t,3} \) defined in  \cref{adam_2}.

\label{bound''}
Suppose that \cref{ass_g_poi} \ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2}, \cref{ass_noise} \ref{ass_noise:i}, \cref{coordinate_0}, \cref{coordinate} \cref{coordinate_i_1} hold. Consider RMSProp. We have
\[\mathbb{E}\left[\sup_{n\ge 1}g(\theta_{n})\right] < +\infty.\]

\label{convergence_1.0'}
Suppose that \cref{ass_g_poi} \ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2}, \cref{ass_noise} \ref{ass_noise:i}, \cref{coordinate_0,coordinate,extra} hold. Consider RMSProp. We have 
\begin{equation}\nonumber\begin{aligned}
\lim_{n\rightarrow\infty}\|\nabla g(\theta_{n})\|=0\ \ \text{a.s.}
\end{aligned}\end{equation}

\label{convergence_2.0'}
Suppose that \cref{ass_g_poi} \ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2}, \cref{ass_noise} \ref{ass_noise:i}, \cref{coordinate_0,coordinate,extra} hold. Consider RMSProp. We have
\begin{equation}\nonumber\begin{aligned}
\lim_{n\rightarrow\infty}\mathbb{E}\|\nabla g(\theta_{n})\|^{2}=0.
\end{aligned}\end{equation}

\label{loss_bound} (Lemma 10 of \cite{jin2022convergence})
Suppose that $g(x)$ is differentiable and lower bounded $ g^{\ast} = \inf_{x\in \ \mathbb{R}^{d}}g(x) >-\infty$ and $\nabla g(x)$ is Lipschitz continuous with parameter $ L > 0$, then $\forall \ x\in \ \mathbb{R}^{d}$, we have
\begin{align*}
\big\|\nabla g(x)\big\|^{2}\le {2 L}\big(g(x)-g^{*}\big).
\end{align*}

 (Theorem 4.2.1 in \cite{Guo2005}) \label{lem_summation_MDS}	
		Suppose that $\{Y_{n}\}\in \mathbb{R}^{d}$ is a $ L_2$ martingale difference sequence, and $(Y_{n},\mathscr{F}_{n})$ is an adaptive process. Then it holds that $\sum_{k=0}^{+\infty}Y_k<+\infty \ a.s.,$ if there exists $p\in (0,2)$ such that 
		\begin{align*}
  \sum_{n=1}^{+\infty}\mathbb{E}[\|Y_{n}\|^{p}]<+\infty,	 \quad   \text{ or }  \quad  \sum_{n=1}^{+\infty}\mathbb{E}\big[\|Y_{n}\|^{p}\big|\mathscr{F}_{n-1}\big]<+\infty. \quad \text{a.s.}
		\end{align*}

\label{sum:expect:ab}
For an adapted process $(Y_{n}, \mathscr{F}_{n})$, and finite stopping times \(a-1,\) \(a\) and \(b\), i.e., $a,\ b<+\infty\ a.s.$
the following equation holds.
\begin{align*}
\mathbb{E}\left[\sum_{n=a}^b Y_n \right] = \mathbb{E}\left[\sum_{n=a}^{b}\mathbb{E}[ Y_n|\mathscr{F}_{n-1}] \right].
\end{align*}

(of \cref{sum:expect:ab})
\begin{align*}
\mathbb{E}\left[\sum_{n=a}^b Y_n \right]&=\mathbb{E}\left[\sum_{n=1}^{b}Y_{n}-\sum_{n=1}^{a-1}Y_{n}\right]=\mathbb{E}\left[\sum_{n=1}^{b}Y_{n}\right]-\mathbb{E}\left[\sum_{n=1}^{a-1}Y_{n}\right]\\&\mathop{=}^{(a)}\mathbb{E}\left[\sum_{n=1}^{b}\mathbb{E}\left[Y_{n}|\mathscr{F}_{n-1}\right]\right]-\mathbb{E}\left[\sum_{n=1}^{a-1}\mathbb{E}\left[Y_{n}|\mathscr{F}_{n-1}\right]\right]\\&=\mathbb{E}\left[\sum_{n=a}^b \mathbb{E}[Y_n|\mathscr{F}_{n-1}] \right],
\end{align*}
where in \emph{$(a)$}, we apply \emph{Doob's stopped} theorem, i.e., for any stopping times \(s < +\infty\ \ a.s.\), we have \(\mathbb{E}\left[\sum_{n=1}^{s} Y_n\right] = \mathbb{E}\left[\sum_{n=1}^{s} \mathbb{E}[Y_n|\mathscr{F}_{n-1}]\right].\)

\label{lem_S_{T}} 
Consider the AdaGrad-Norm algorithm in  \cref{AdaGrad_Norm} and suppose that   \cref{ass_g_poi}~\ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2} and  \cref{ass_noise}~\ref{ass_noise:i}$\sim$ \ref{ass_noise:i2} hold. For any initial point $\theta_{1}\in \mathbb{R}^{d}, S_{0}>0$, and $T \geq 1$, let $\zeta =\sqrt{S_{0}}+\sum_{n=1}^{\infty}\|\nabla g(\theta_{n},\xi_{n})\|^{2}/n^2$. The following results hold.
\begin{itemize}
\item[(a)]  $\mathbb{E}(\zeta)$ is uniformly upper bounded by a constant, which depends on $\theta_1, \sigma_0, \sigma_1, \alpha_0,  L, S_0$.
\item[(b)] $S_T$ is upper bounded by $(1+\zeta)^2T^4$.
\end{itemize}

(of \cref{lem_S_{T}})
Recalling the sufficient decrease inequality in \cref{sufficient:lem}
\begin{align*}
\hat{g}(\theta_{n+1})-\hat{g}(\theta_{n}) & \le -\frac{\alpha_{0}}{4}\zeta(n)+C_{\Gamma,1}\cdot \Gamma_n  +C_{\Gamma,2}\frac{\Gamma_{n}}{\sqrt{S_{n}}}  + \alpha_0 \hat{X}_{n}.
\end{align*}
Dividing both sides of the inequality by $n^2\alpha_0/4$, we obtain
\begin{align}\label{zxc_09}
\frac{1}{n^{2}} \zeta(n) &\le \frac{4}{\alpha_0n^{2}}\big(\hat{g}(\theta_{n})-\hat{g}(\theta_{n+1})\big)+\frac{4C_{\Gamma,1}}{\alpha_0}\cdot\frac{\Gamma_n}{n^{2}}  +\frac{4C_{\Gamma,2}}{\alpha_0}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^2 S_{n}^{\frac{3}{2}}}+\frac{4 \hat{X}_{n}}{n^{2}}.
\end{align}
For the second term on the RHS of \cref{zxc_09}, we use \emph{Young's inequality} and $S_n \geq S_{n-1}$:
\begin{equation}\nonumber\begin{aligned}
 \frac{4C_{\Gamma,1}}{\alpha_0}\cdot\frac{\Gamma_n}{n^{2}} &\le \frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{2n^{2}\sqrt{S_{n}}}+\frac{16C_{\Gamma,1}^2}{\alpha_0^2}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{2n^2S_{n}^{\frac{3}{2}}}  \le \frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{2n^{2}\sqrt{S_{n-1}}}+\frac{16C_{\Gamma,1}^2}{\alpha_0^2}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{2n^2S_{n}^{\frac{3}{2}}}.
\end{aligned}\end{equation}
Substituting the above inequality into \cref{zxc_09} gives
\begin{align*}
\frac{\zeta(n)}{2n^{2}}  &\le \frac{4}{\alpha_0n^{2}}\big(\hat{g}(\theta_{n})-\hat{g}(\theta_{n+1})\big)+\left(\frac{4C_{\Gamma,2}}{\alpha_0} + \frac{8C_{\Gamma,1}^2}{\alpha_0^2}\right)\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^2 S_{n}^{\frac{3}{2}}}    +\frac{4 \hat{X}_{n}}{n^{2}}.
\end{align*}
Telescoping the indices \( n \) from 1 to \( T \) over the above inequality, we have
\begin{align}\label{inequ:sequence:1}
\sum_{n=1}^{T} \frac{1}{2n^2}\zeta(n) &\le \sum_{n=1}^{T} \frac{4}{\alpha_0n^{2}}\big(\hat{g}(\theta_{n})-\hat{g}(\theta_{n+1})\big) +\mathcal{C}_1 \sum_{n=1}^T\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^2 S_{n}^{\frac{3}{2}}}  + 4\sum_{n=1}^{T}\frac{\hat{X}_{n}}{n^{2}},
\end{align}
where we use $\mathcal{C}_1$ to denote the coefficient constant factor of $\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^2 S_{n}^{\frac{3}{2}}}$ to simplify the expression. For the first term of RHS of \cref{inequ:sequence:1}, since $\hat{g}(\theta_n) = g(\theta_n) + \sigma_0\alpha_0\zeta(n)/2 \geq 0$ for all $n \geq 1$, we have 
\begin{align}
& \sum_{n=1}^{T}\frac{1}{n^{2}}\big(\hat{g}(\theta_{n})-\hat{g}(\theta_{n+1})\big) =  \sum_{n=1}^{T} \frac{\hat{g}(\theta_{n})}{n^2}-\frac{\hat{g}(\theta_{n+1})}{(n+1)^2} + \frac{\hat{g}(\theta_{n+1})}{(n+1)^{2}} - \frac{\hat{g}(\theta_{n+1})}{n^{2}} \notag \\
=  &\sum_{n=1}^{T} \frac{\hat{g}(\theta_{n})}{n^2}-\frac{\hat{g}(\theta_{n+1})}{(n+1)^2} - \frac{\hat{g}(\theta_{n+1})(2n+1)}{(n+1)^{2}n^2}  \leq  \hat{g}(\theta_1).
\end{align}
For the second term of RHS of \cref{inequ:sequence:1}, we utilized the series-integral result
\[\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^2 S_{n}^{\frac{3}{2}}} \leq \sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}^{\frac{3}{2}}}<\int_{S_{0}}^{+\infty}\frac{1}{x^{\frac{3}{2}}}\text{d}x=\frac{2}{\sqrt{S_{0}}}.\]
Applying the above estimations into \cref{inequ:sequence:1} and taking the mathematical expectation on both sides, we have $\forall\ n\ge 1,$
\begin{align}\label{inequ:sequence:expect}
\sum_{n=1}^{T}\frac{\mathbb{E}\left[\zeta(n)\right]}{2n^2} &\le \frac{4}{\alpha_0} \hat{g}(\theta_1) + \frac{2}{\sqrt{S_0}}\mathcal{C}_1   + 4\sum_{n=1}^{T}\frac{\mathbb{E}[\hat{X}_{n}]}{n^{2}} = \frac{4}{\alpha_0} \hat{g}(\theta_1) + \frac{2}{\sqrt{S_0}}\mathcal{C}_1,
\end{align}
since $\lbrace \hat{X}_{n}, \mathscr{F}_{n-1}\rbrace$ is a martingale difference sequence. According to \emph{the affine noise variance condition}, we obtain:
\begin{align}\label{adagrad_100-1}
\sum_{n=1}^{T}\frac{\mathbb{E}\left[\zeta(n)\right]}{2n^2}\ge \sum_{n=1}^{T}\frac{\mathbb{E}\left[\|\nabla g(\theta_{n},\xi_{n})\|^{2}\right]}{2\sigma_{0}n^2}-\frac{\sigma_{1}}{2\sigma_{0}}\sum_{n=1}^{T}\frac{1}{n^{2}}\mathop{\ge}^{(a)} \sum_{n=1}^{T}\frac{\mathbb{E}\left[\|\nabla g(\theta_{n},\xi_{n})\|^{2}\right]}{2\sigma_{0}n^2}-\frac{\sigma_{1}\pi^{2}}{12\sigma_{0}}.
\end{align}
Here, $(a)$ uses the inequity \[\sum_{n=1}^{T}\frac{1}{n^{2}}<\sum_{n=1}^{+\infty}\frac{1}{n^{2}}=\frac{\pi^{2}}{6}.\] 
Combining \cref{inequ:sequence:expect} with \cref{adagrad_100-1}, we obtain
\begin{align*}
\mathbb{E}\bigg[\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{2\sigma_{0}n^{2}}\bigg]=\sum_{n=1}^{T}\frac{\mathbb{E}\left[\|\nabla g(\theta_{n},\xi_{n})\|^{2}\right]}{2\sigma_{0}n^2}\le \frac{\sigma_{1}\pi^{2}}{12\sigma_{0}}+\frac{4}{\alpha_0} \hat{g}(\theta_1) + \frac{2}{\sqrt{S_0}}\mathcal{C}_1.
\end{align*}
By \emph{Lebesgue monotone convergence} theorem, we further get that $\zeta=\sqrt{S_{0}}+\sum_{n=1}^{+\infty}\|\nabla g(\theta_{n},\xi_{n})\|^{2}\big/n^{2}<+\infty\ \ a.s.,$ and
\begin{equation}\label{zxc_10}\begin{aligned}
\mathbb{E}[\zeta]=\sqrt{S_{0}}+\mathbb{E}\bigg[\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^{2}}\bigg] \leq   \sqrt{S_{0}}+\frac{\sigma_{0}\sigma_{1}\pi^{2}}{6\sigma_{0}}+\frac{16\sigma_{0}}{\alpha_0} \hat{g}(\theta_1) + \frac{8\sigma_{0}}{\sqrt{S_0}}\mathcal{C}_1.
\end{aligned}\end{equation}
Next, we derive the relationship of $S_T$ and the $\zeta$. Note that $\forall\ T\ge 1,$
\[\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^{2}\sqrt{S_{n-1}}}>\frac{1}{T^{2}\sqrt{S_{T}}}\sum_{n=1}^{T}\|\nabla g(\theta_{n},\xi_{n})\|^{2}=\frac{S_T -S_0}{T^{2}\sqrt{S_{T}}} .\] We have
\begin{equation}\nonumber\begin{aligned}
\sqrt{S_T} &\leq \bigg(\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^{2}\sqrt{S_{n-1}}}\bigg) \cdot T^2+ \sqrt{S_0}  \leq \bigg(\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{n^{2}\sqrt{S_{n-1}}} + \sqrt{S_0} \bigg)\cdot T^2=\zeta\cdot T^{2}\\&<(1+\zeta)\cdot T^{2},
\end{aligned}\end{equation}
as we desired.

(of \cref{lem:estimation:supg})
For any $T\geq 1,$ we calculate \(\mathbb{E}\left(\sup_{n \ge 1} g(\theta_{n})\right)\) based on the segment of $g$ on the stopping time
\begin{align}\label{start}
  &\quad \mathbb{E}\Big[\sup_{1\le n<T}g(\theta_{n})\Big] \notag \\&\le \mathbb{E}\Big[\sup_{1\le n< \tau_{1,T}}g(\theta_{n})\Big]  +\mathbb{E}\Big[\sup_{\tau_{1,T}\le n<T}g(\theta_{n})\Big]\notag\\&=\mathbb{E}\Big[\mathbb{I}_{[\tau_{1,T}=1]}\sup_{1\le n< \tau_{1,T}}g(\theta_{n})\Big]+\underbrace{\mathbb{E}\Big[\mathbb{I}_{[\tau_{1,T}>1]}\sup_{1\le n< \tau_{1,T}}g(\theta_{n})\Big]}_{\Pi_{1, T}} +\underbrace{\mathbb{E}\Big[\sup_{\tau_{1,T}\le n< T}g(\theta_{n})\Big]}_{\Pi_{2,T}}\notag\\&\mathop{\le}^{(a)}0+\Delta_{0}+\Pi_{2,T},
\end{align}
where we define $\tau_{t,T}:=\tau_{t}\wedge T.$ 
To make the inequality consistent, we let $\sup_{a \le t < b}(\cdot) = 0 \ (\forall\ a \ge b).$ For $(a)$ in \cref{start}, since $\tau_{1,T} \geq 1$, we have  $\mathbb{E}\Big[\mathbb{I}_{[\tau_{1,T}=1]}\sup_{1\le n< \tau_{1,T}}g(\theta_{n})\Big]=0$ and
\begin{align*}
\Pi_{1, T}&=\mathbb{E}\Big[\mathbb{I}_{[\tau_{1,T}>1]}\sup_{1\le n< \tau_{1,T}}g(\theta_{n})\Big]\le\mathbb{E}\Big[\mathbb{I}_{[\tau_{1}>1]}\sup_{1\le n< \tau_{1,T}}g(\theta_{n})\Big]\le\Delta_{0}.
\end{align*}
Next, we focus on  $\Pi_{2,T}$. Specifically, we have:
\begin{align}\label{inequ:xt2}
\Pi_{T,2}&=\mathbb{E}\Big[\sup_{\tau_{1,T}\le n<T}g(\theta_{n})\Big]=\mathbb{E}\bigg[\sup_{i\ge 1}\Big(\sup_{\tau_{3i-2,T}\le n<\tau_{3i+1,T}}g(\theta_n)\Big)\bigg]\notag\\&\le\underbrace{\mathbb{E}\bigg[\Big(\sup_{\tau_{1,T}\le n<\tau_{4,T}}g(\theta_n)\Big)\bigg]}_{\Pi_{2,T}^1}+\underbrace{\mathbb{E}\bigg[\sup_{i\ge 2}\Big(\sup_{\tau_{3i-2,T}\le n<\tau_{3i+1,T}}g(\theta_n)\Big)\bigg]}_{\Pi_{2,T}^2}.
\end{align}
We decompose $\Pi_{2,T}$ into $\Pi_{2,T}^1$ and $\Pi_{2,T}^2$ and estimate them separately. For the term $\Pi_{2,T}^1$ we have
\begin{align}\label{inequ:xt21}
    \Pi_{2,T}^1& = \mathbb{E}\bigg[\Big(\sup_{\tau_{1,T}\le n<\tau_{3,T}}g(\theta_n)\Big)\bigg]+\mathbb{E}\bigg[\Big(\sup_{\tau_{3,T}\le n<\tau_{4,T}}g(\theta_n)\Big)\bigg] \notag \\
    & \mathop{\le}^{\text{\cref{fab_2}}} \mathbb{E}\bigg[\Big(\sup_{\tau_{1,T}\le n<\tau_{3,T}}g(\theta_n)\Big)\bigg]+\Delta_{0}\notag\\&=\mathbb{E}[g(\theta_{\tau_{1,T}})]+\mathbb{E}\bigg[\Big(\sup_{\tau_{1,T}\le n<\tau_{3,T}}(g(\theta_n)-g(\theta_{\tau_{1,T}}))\Big)\bigg]+\Delta_{0}\notag\\
&=\mathbb{E}[\mathbb{I}_{[\tau_{1}=1]}g(\theta_{\tau_{1}})]+\mathbb{E}[\mathbb{I}_{[\tau_{1}>1]}g(\theta_{\tau_{1}})]+\mathbb{E}\bigg[\Big(\sup_{\tau_{1,T}\le n<\tau_{3,T}}(g(\theta_n)-g(\theta_{\tau_{1,T}}))\Big)\bigg]+\Delta_{0}\notag\\&\mathop{\le}^{(a)}g(\theta_{1})+\Big(\Delta_{0}+\alpha_{0}\sqrt{2 L\Delta_{0}}+\frac{ L\alpha_{0}^{2}}{2}\Big)+\mathbb{E}\bigg[\Big(\sup_{\tau_{1,T}\le n<\tau_{3,T}}(g(\theta_n)-g(\theta_{\tau_{1,T}}))\Big)\bigg] + \Delta_{0}\notag\\&\mathop{\le}^{(b)}g(\theta_{1})+2\Delta_{0}+\alpha_{0}\sqrt{2 L\Delta_{0}}+\frac{ L\alpha_{0}^{2}}{2} + C_{\Pi,1} \mathbb{E}\Bigg[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1} \zeta(n)\Bigg],
\end{align}
where $C_{\Pi,1}$ is a constant and is defined in \cref{inqu:diff:g:tau1}.
For $(a)$ of \cref{inequ:xt21}, we follow the fact that $\mathbb{E}\Big[\mathbb{I}_{[\tau_{1,T}>1]}g(\theta_{\tau_{1,T}-1})\Big]\le \Delta_{0}$ and  get that
\begin{align*}
\mathbb{E}[\mathbb{I}_{[\tau_{1}>1]}g(\theta_{\tau_{1,T}})]&=\mathbb{E}[\mathbb{I}_{[\tau_{1}>1]}g(\theta_{\tau_{1,T}-1})]+\mathbb{E}[\mathbb{I}_{[\tau_{1}>1]}g(\theta_{\tau_{1,T}})-g(\theta_{\tau_{1,T}-1})]\\&\mathop{\le}^{\text{\cref{inequ:g:adj}}} \Delta_{0}+\alpha_{0}\sqrt{2 L\Delta_{0}}+\frac{ L\alpha_{0}^{2}}{2}.
\end{align*}
For (b) we use the one-step iterative formula on $g$ 
   \begin{align}\label{inequ:one:g:adj}
       g(\theta_{n+1})-g(\theta_{n})&\le \nabla g(\theta_{n})^{\top}(\theta_{n+1}-\theta_{n})+\frac{ L}{2}\|\theta_{n+1}-\theta_{n}\|^{2} \notag \\&\le\frac{\alpha_{0}\|\nabla g(\theta_{n})\|\|\nabla g(\theta_{n},\xi_{n})\|}{\sqrt{S_{n}}}+\frac{ L\alpha_{0}^{2}}{2}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}} \notag \\
       & \leq \frac{\alpha_{0}\|\nabla g(\theta_{n})\|}{\sqrt{S_{n-1}}} \|\nabla g(\theta_{n},\xi_{n})\|+\frac{ L\alpha_{0}^{2}}{2}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{\sqrt{S_0}\sqrt{S_{n-1}}},
   \end{align}
   which induces that (recall that $\zeta_n = \|\nabla g(\theta_{n},\xi_{n})\|^{2}/\sqrt{S_{n-1}}$)
\begin{align}\label{inqu:diff:g:tau1}
&\quad \mathbb{E}\bigg[\Big(\sup_{\tau_{1,T}\le n<\tau_{3,T}}(g(\theta_n)-g(\theta_{\tau_{1,T}}))\Big)\bigg]
\le  \mathbb{E}\Bigg[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}|g(\theta_{n+1})-g(\theta_{n})|\Bigg] \notag\\& \le \mathbb{E}\Bigg[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\frac{\alpha_{0}\|\nabla g(\theta_{n})\|\cdot\|\nabla g(\theta_{n},\xi_{n})\|}{\sqrt{S_{n-1}}}\Bigg]+\mathbb{E}\Bigg[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\frac{ L\alpha^{2}_{0}\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{2\sqrt{S_0}\sqrt{S_{n-1}}}\Bigg] \notag \\&\mathop{=}^{(a)}\mathbb{E}\left[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\frac{\alpha_{0}\|\nabla g(\theta_{n})\|}{\sqrt{S_{n}}}\mathbb{E}\left(\|\nabla g(\theta_{n},\xi_{n})\| \mid \mathscr{F}_{n-1}\right)+\frac{ L\alpha_{0}^{2}}{2\sqrt{S_{0}}}\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\frac{\mathbb{E} \left(\|\nabla g(\theta_{n},\xi_{n})\|^{2} \mid \mathscr{F}_{n-1}\right) }{\sqrt{S_{n-1}}}\right]
\notag 
\\&\mathop{\le}^{(*)}\bigg(\alpha_{0}\Big(\sqrt{\sigma_{0}}+\sqrt{\frac{\sigma_{1}}{\eta}}\Big)+\frac{ L\alpha_{0}^{2}}{2\sqrt{S_{0}}}\Big(\sigma_{0}+\frac{\sigma_{1}}{\eta}\Big)\bigg)\mathbb{E}\Bigg[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\zeta(n)\Bigg] := C_{\Pi,1}\mathbb{E}\Bigg[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\zeta(n)\Bigg],
\end{align}
where (a) uses \cref{sum:expect:ab}.
If $\tau_{1,T} > \tau_{3,T} - 1$, inequality $(*)$ trivially holds since $\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\cdot=0$. Moving forward we will exclusively examine the case $\tau_{1,T} \le \tau_{3,T} - 1$. By the definition of $\tau_t$, we have $\hat{g}(\theta_n) > \Delta_0 \geq \hat{C}_g$ for any $n \in [\tau_{1,T}, \tau_{3,T})$. Consequently, upon applying \cref{pro_0}, we deduce that $\|\nabla g(\theta_{n})\|^{2} > \eta$ for any $n \in [\tau_{1,T}, \tau_{3,T})$. Combined with the affine noise variance condition, we further achieve the subsequent inequalities that for any $n\in[\tau_{1,T},\tau_{3,T})$
\begin{align}\label{asddsaasd}
    \mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\|^{2}|\mathscr{F}_{n-1}]&\le {\sigma_{0}}\|\nabla g(\theta_{n})\|^{2}+{\sigma_{1}} 
     < \Big({\sigma_{0}}+{\frac{\sigma_{1}}{{\eta}}}\Big)\cdot\|\nabla g(\theta_{n})\|^{2}
\end{align}
and
\begin{align}\label{asddsa}
    &\quad \mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\||\mathscr{F}_{n-1}]  \leq \left(\mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\|^2|\mathscr{F}_{n-1}) \right]^{1/2} \leq \Big({\sigma_{0}}\|\nabla g(\theta_{n})\|^{2}+{\sigma_{1}}\Big)^{1/2} \notag \\
    &\le \sqrt{\sigma_{0}}\|\nabla g(\theta_{n})\|+\sqrt{\sigma_{1}} <\Big(\sqrt{\sigma_{0}}+\sqrt{\frac{\sigma_{1}}{{\eta}}}\Big)\cdot\|\nabla g(\theta_{n})\|.
\end{align}
Next, we turn to estimate $\Pi_{2,T}^2$.
\begin{align}\label{qaswert}
   \Pi_{2,T}^2&={\mathbb{E}\bigg[\sup_{i\ge 2}\Big(\sup_{\tau_{3i-2,T}\le n<\tau_{3i+1,T}}g(\theta_n)\Big)\bigg]}\notag\\&\le \mathbb{E}\bigg[\sup_{i\ge 2}\Big(\sup_{\tau_{3i-2,T}\le n<\tau_{3i-1,T}}g(\theta_n)\Big)\bigg]+\mathbb{E}\bigg[\sup_{i\ge 2}\Big(\sup_{\tau_{3i-1,T}\le n<\tau_{3i,T}}g(\theta_n)\Big)\bigg]\notag\\&\quad +\mathbb{E}\bigg[\sup_{i\ge 2}\Big(\sup_{\tau_{3i,T}\le n<\tau_{3i+1,T}}g(\theta_n)\Big)\bigg]\notag\\&\mathop{\le}^{(a)} 2\Delta_{0}+\mathbb{E}\bigg[\sup_{i\ge 2}\Big(\sup_{\tau_{3i-1,T}\le n<\tau_{3i,T}}g(\theta_n)\Big)\bigg]+\Delta_{0}\notag\\&\le 3\Delta_{0}+\mathbb{E}\Big[\sup_{n=\tau_{3i-1,T}}{g}(\theta_{n})\Big]+\mathbb{E}\Big[\sup_{i\ge 2}\sup_{\tau_{3i-1,T}\le n\le \tau_{3i,T}}(g(\theta_{n})-g(\theta_{\tau_{3i-1,T}}))\Big]\notag\\&\mathop{\le}^{(b)}3\Delta_{0}+\Big(2\Delta_0+2\alpha_{0}\sqrt{ L\Delta_0}+\frac{ L\alpha_{0}^{2}}{2}\Big) + C_{\Pi,1}\mathbb{E}\Bigg[\sum_{i=2}^{+\infty}\sum_{\tau_{3i-1,T}}^{\tau_{3i,T}-1}\zeta(n)\Bigg],
\end{align}
where $(a)$ follows from \cref{fab_2} and \cref{fabulous}. To derive $(b)$, we first use the following estimation of $g(\theta_n)$ at the stopping time $\tau_{3i-1,T}$  
\begin{align*}
\sup_{n=\tau_{3i-1,T}}{g}(\theta_{n})&=\sup_{n=\tau_{3i-1,T}}{g}(\theta_{n-1})+\sup_{n=\tau_{3i-1,T}}({g}(\theta_{n})-g(\theta_{n-1}))\\&\mathop{\le}^{\text{\cref{inequ:g:adj}}} 2\Delta_{0}+2\alpha_{0}\sqrt{ L\Delta_{0}}+\frac{ L\alpha_{0}^{2}}{2}.
\end{align*}
Then, since the objective $g(\theta_n)$ in the interval $ n \in [\tau_{3i-1,T},\tau_{3i,T})$ has similar properties as the interval $[\tau_{1,T},\tau_{3,T})$, we follow the same procedure as \cref{inqu:diff:g:tau1}  to estimate the supremum of $g(\theta_{n})-g(\theta_{\tau_{3i-1,T}})$ on the interval $ n \in [\tau_{3i-1,T}, \tau_{3i,T})$, it achieves that 
\begin{align}\label{inqu:diff:g:tau2}
&\quad \mathbb{E} \left[\sup_{i\ge 2}\sup_{\tau_{3i-1,T}\le n\le \tau_{3i,T}}(g(\theta_{n})-g(\theta_{\tau_{3i-1,T}}))\right] \leq \mathbb{E} \left[\sum_{i=2}^{+\infty}\sup_{\tau_{3i-1,T}\le n\le \tau_{3i,T}}(g(\theta_{n})-g(\theta_{\tau_{3i-1,T}}))\right]  \notag \\
& \leq \bigg(\alpha_{0}\Big(\sqrt{\sigma_{0}}+\sqrt{\frac{\sigma_{1}}{\eta}}\Big)+\frac{ L\alpha_{0}^{2}}{2\sqrt{S_{0}}}\Big(\sigma_{0}+\frac{\sigma_{1}}{\eta}\Big)\bigg)\mathbb{E}\Bigg[\sum_{i=2}^{+\infty}\sum_{n=\tau_{3i-1,T}}^{\tau_{3i,T}-1}\zeta(n)\Bigg].
\end{align}
By substituting the estimations of $\Pi_{2,T}^1$ and $\Pi_{2,T}^2$ from \cref{inequ:xt21} and \cref{qaswert} respectively into \cref{inequ:xt2}, we achieve the estimation for $\Pi_{2,T}$. Then, substituting the result for $\Pi_{2,T}$ into \cref{start} gives
\begin{align}\label{wxm_200}
\mathbb{E}\Big[\sup_{1\le n<T}g(\theta_{n})\Big]\le C_{\Pi,0}+C_{\Pi, 1}\underbrace{\mathbb{E}\Bigg[\sum_{n=\tau_{1,T}}^{\tau_{3,T}-1}\zeta(n)+\sum_{i=2}^{+\infty}\sum_{\tau_{3i-1,T}}^{\tau_{3i,T}-1}\zeta(n)\Bigg]}_{\Pi_{3,T}},
\end{align}
where
\begin{align}\label{constant_Pi}
C_{\Pi,0}&=g(\theta_{1})+6\Delta_{0}+5\alpha_{0}\sqrt{ L\Delta_{0}}+\frac{3 L\alpha_{0}^{2}}{2}, C_{\Pi,1}=\alpha_{0}\Big(\sqrt{\sigma_{0}}+\sqrt{\frac{\sigma_{1}}{\eta}}\Big)+\frac{ L\alpha_{0}^{2}}{2\sqrt{S_{0}}}\Big(\sigma_{0}+\frac{\sigma_{1}}{\eta}\Big).
\end{align}
Next, we turn to find an upper bound for $\Pi_{3,T}$ which is independent of $T$. Recall the sufficient decrease inequality in \cref{sufficient:lem}
\begin{align*}
\hat{g}(\theta_{n+1})-\hat{g}(\theta_{n}) & \le -\frac{\alpha_{0}}{4}\zeta_{n}+C_{\Gamma,1}\cdot \Gamma_n  +C_{\Gamma,2}\frac{\Gamma_{n}}{\sqrt{S_{n}}} + \alpha_0 \hat{X}_{n}.
\end{align*}
First, we estimate the first term of $\Pi_{3,T}$. Telescoping the above inequality over $n$ from the interval \(I_{1,\tau}:=[\tau_{1,T},\tau_{3,T}-1]\)  gives
\begin{align*}
\frac{\alpha_{0}}{4}\sum_{n \in I_{1,\tau}}\zeta(n)&\le \hat{g}(\theta_{\tau_{1,T}})-\hat{g}(\theta_{\tau_{3,T}})+C_{\Gamma,1}\sum_{n \in I_{1,\tau}} \Gamma_n+C_{\Gamma,2}\sum_{n \in I_{1,\tau}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}+\alpha_0 \sum_{n \in I_{1,\tau}}\hat{X}_{n}.
\end{align*} 
Taking the expectation on both sides of the above inequality, we have
\begin{align*}
\frac{\alpha_{0}}{4}\mathbb{E}\left[\sum_{n \in I_{1,\tau}}\zeta(n)\right]&\le\mathbb{E}\big[\hat{g}(\theta_{\tau_{1,T}})\big]+C_{\Gamma,1}\mathbb{E}\bigg[\sum_{n \in I_{1,\tau}} \Gamma_n \bigg]+C_{\Gamma,2}\mathbb{E}\Bigg[\sum_{n \in I_{1,\tau}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]+\alpha_0\mathbb{E}\Bigg[\sum_{n \in I_{1,\tau}}\hat{X}_{n}\Bigg]\notag\\&\mathop{\le}^{(a)} \mathbb{E}\big[\hat{g}(\theta_{\tau_{1,T}})\big]+C_{\Gamma,1}\mathbb{E}\bigg[\sum_{n \in I_{1,\tau}} \mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\bigg]+C_{\Gamma,2}\mathbb{E}\Bigg[\sum_{n \in I_{1,\tau}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]+0,
\end{align*}
where for (a), we use \text{\emph{Doob's Stopped} theorem} (see \cref{vital1}) since the stopping times $\tau_{1,T}\le \tau_{3,T}-1$ and $\hat{X}_n$ is a martingale sequence. For the first term of the RHS of the above inequality,
\begin{align*}
\mathbb{E}\big[\hat{g}(\theta_{\tau_{1,T}})\big]&=\mathbb{E}\big[\mathbb{I}_{[\tau_{1}=1]}\hat{g}(\theta_{1})\big]+\mathbb{E}\big[\mathbb{I}_{\tau_{1}>1}\hat{g}(\theta_{\tau_{1,T}})\big] \\&\le \hat{g}(\theta_{1})+ \mathbb{E}\big[\mathbb{I}_{\tau_{1}>1}\hat{g}(\theta_{\tau_{1,T}-1})\big]+\mathbb{E}\big[\mathbb{I}_{\tau_{1}>1}(\hat{g}(\theta_{\tau_{1,T}})-\hat{g}(\theta_{\tau_{1,T}-1}))\big]\\&\mathop{\le}^{\text{\cref{lem:adj:ghat}}} \hat{g}(\theta_{1})+\Delta_{0}+h(\Delta_{0})<\hat{g}(\theta_{1})+\frac{3\Delta_{0}}{2}.
\end{align*}
We thus conclude that 
\begin{align}\label{inequ:stat:1'}
\frac{\alpha_{0}}{4}\mathbb{E}\left[\sum_{n \in I_{\tau,1}}\zeta(n)\right]&\le\hat{g}(\theta_{1})+\frac{3\Delta_{0}}{2}+C_{\Gamma,1}\mathbb{E}\bigg[\sum_{n \in I_{\tau,i}} \mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}] \bigg]+C_{\Gamma,2}\mathbb{E}\Bigg[\sum_{n \in I_{\tau,i}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg].
\end{align}
For the second term of $\Pi_{3,T}$, we telescope the sufficient decrease inequality in \cref{sufficient:lem} over $n$ from the interval \( I_{i,\tau}^{'}:= [\tau_{3i-1,T}, \tau_{3i,T}-1 ]\ (\forall\ i\ge 2)\)
\begin{align}\label{inequ:stab:2}
\frac{\alpha_{0}}{4}\sum_{n \in I_{i,\tau}^{'}}\zeta(n)&\le \hat{g}(\theta_{\tau_{3i-1,T}})-\hat{g}(\theta_{\tau_{3i,T}})+C_{\Gamma,1}\sum_{n \in I_{i,\tau}^{'}} \Gamma_n+C_{\Gamma,2}\sum_{n \in I_{i,\tau}^{'}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}+\alpha_0 \sum_{n \in I_{i,\tau}^{'}}\hat{X}_{n}.
\end{align} 
Recalling the definition of the stopping time $\tau_t$, we know that \(\tau_{3i,T} \geq \tau_{3i-1,T}\) always holds. In particular, \(\tau_{3i,T} = \tau_{3i-1,T}\) implies that \(\tau_{3i,T}-1 < \tau_{3i-1,T}\). Since $\sum_{n=a}^b(\cdot) = 0$ for $b  <  a$, we have  $\sum_{n=\tau_{3i-1,T}}^{\tau_{3i,T}-1}(\cdot) = 0 $ and $\hat{g}(\theta_{\tau_{3i,T}}) = \hat{g}(\theta_{\tau_{3i-1,T}})$, then LHS and RHS of \cref{inequ:stab:2} are both zero and \cref{inequ:stab:2} holds. Taking the expectation on both sides and noting the equation of \cref{sum:expect:ab} gives
\begin{align}\label{inequ:stat:1}
\frac{\alpha_{0}}{4}\mathbb{E}\left[\sum_{n \in I_{i,\tau}^{'}}\zeta(n)\right]&\le \mathbb{E}\big[\hat{g}(\theta_{\tau_{3i-1,T}})-\hat{g}(\theta_{\tau_{3i,T}})\big]+C_{\Gamma,1}\mathbb{E}\bigg[\sum_{n \in I_{i,\tau}^{'}} \mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}] \bigg]\notag\\&+C_{\Gamma,2}\mathbb{E}\Bigg[\sum_{n \in I_{i,\tau}^{'}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]+0.
\end{align}
If \(\tau_{3i-1, T} <  \tau_{3i, T}\),  for any $n \in I_{i,\tau}^{'} = [\tau_{3i-1,T}, \tau_{3i,T}-1]$, by applying \cref{lem:adj:ghat} we have
\begin{align*}
\hat{g}(\theta_{\tau_{3i-1, T}}) - \hat{g}(\theta_{\tau_{3i,T}})&<\hat{g}(\theta_{\tau_{3i-1,T}}) <  \hat{g}(\theta_{\tau_{3i-1,T}-1})+h(\hat{g}(\theta_{\tau_{3i-1,T}-1})).
\end{align*}
Based on the properties of the stopping time \(\tau_{3i-1},\) we have $\hat{g}(\theta_{\tau_{3i-1,T}-1}) \leq 2\Delta_{0}.$ Based on the above inequality, we further estimate the first term of  \cref{inequ:stat:1} and achieve that
\begin{align}\label{wxm_90}
\frac{\alpha_{0}}{4}\mathbb{E}\Bigg[\sum_{n=I_{i,\tau}^{'}}\zeta(n)\Bigg]\notag&\le C_{\Delta_{0}}\mathbb{E}\big[\mathbb{I}_{\{\tau_{3i-1,T}<\tau_{3i,T} \}}\big]+C_{\Gamma,1}\mathbb{E}\bigg[\sum_{n=I_{i,\tau}^{'}} \mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}] \bigg] \\&+C_{\Gamma,2}\mathbb{E}\Bigg[\sum_{n=I_{i,\tau}^{'}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]  ,
\end{align}
where
\begin{align}\label{inequ:C:Delta0}
C_{\Delta_{0}}: =2\Delta_{0}+ \sqrt{2 L}\left(1 + \frac{\sigma_0 L}{2\sqrt{S_0}}\right)\alpha_0\sqrt{2\Delta_0} + \left(1  + \frac{\sigma_0\alpha_0 L}{2\sqrt{S_0}}\right)\frac{ L\alpha_0^2}{2}.
\end{align}
Telescoping \cref{wxm_90} over $i$ from \(2\) to \(+\infty\) to estimate the second part of $\Pi_{3,T}$, we have
\begin{align}\label{pqwe_1}
\frac{\alpha_{0}}{4}\mathbb{E}\left[\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}}\zeta(n)\right]\le& C_{\Delta_{0}}\cdot\sum_{i=2}^{+\infty}\mathbb{E}\big[\mathbb{I}_{\tau_{3i-1,T}<\tau_{3i,T}}\big]+C_{\Gamma,1}\sum_{i=2}^{+\infty}\mathbb{E}\bigg[\sum_{n=I_{i,\tau}^{'}} \mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\bigg] \notag \\&+C_{\Gamma,2}\sum_{i=2}^{+\infty}\mathbb{E}\Bigg[\sum_{n=I_{i,\tau}^{'}}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg].
\end{align}
Note that the stopping time \(\tau_{t}\) is truncated for any finite time \(T\). For a specific $T$, the sum \(\sum_{i=2}^{+\infty}\) has only finite non-zero terms, thus we can interchange the order of summation and expectation \(\mathbb{E}\left(\sum_{i=2}^{+\infty} (\cdot) \right) = \sum_{i=2}^{+\infty} \left(\mathbb{E}(\cdot) \right).\) Substituting \cref{pqwe_1} and \cref{inequ:stat:1'} into \cref{wxm_200} gives
\begin{align}\label{wxm_110}
&\mathbb{E}\Big[\sup_{1\le n< T}g(\theta_{n})\Big]\notag \\
\le&\ \overline{C}_{\Pi,0}+ C_{\Pi,1}C_{\Delta_{0}}\cdot\sum_{i=2}^{+\infty}\underbrace{\mathbb{E}\big[\mathbb{I}_{\tau_{3i-1,T}<\tau_{3i,T}}\big]}_{\Psi_{i,1}}+C_{\Pi,1}C_{\Gamma,1}\underbrace{\mathbb{E}\left[\bigg(\sum_{I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\right]}_{\Psi_{2}} \notag \\&\quad +C_{\Pi,1}C_{\Gamma,2}\underbrace{\mathbb{E}\Bigg[\bigg(\sum_{n=I_{1,\tau}}+\sum_{i=2}^{+\infty}\sum_{n=I_{i,\tau}^{'}} \bigg)\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]}_{\Psi_{3}},
\end{align}
where $\overline{C}_{\Pi,0}:=\hat{g}(\theta_{1})+\frac{3\Delta_{0}}{2}+C_{\Pi,0}.$

