(of \cref{lem_su})
Due to \cref{sufficient:lem}, we know
\begin{align}\label{jh_20}
\hat{g}(\theta_{n+1})-\hat{g}(\theta_{n}) & \le -\frac{\alpha_{0}}{4}\zeta(n)+C_{\Gamma, 1}\cdot \Gamma_n  + C_{\Gamma, 2}\frac{\Gamma_{n}}{\sqrt{S_{n}}} + \alpha_0 \hat{X}_{n},
\end{align}
Then we define an auxiliary variable $ y_{n} := \frac{1}{\sqrt{S_{n-1}}}$. Multiplying both sides of \cref{jh_20} by this auxiliary variable, we obtain
\begin{align*}
y_{n}\hat{g}(\theta_{n+1})-y_{n}\hat{g}(\theta_{n}) & \le  -\frac{\alpha_{0}}{4}y_{n}\zeta(n)+C_{\Gamma, 1}\cdot y_{n}\Gamma_n  + C_{\Gamma, 2}y_{n}\frac{\Gamma_{n}}{\sqrt{S_{n}}} + \alpha_0 y_{n}\hat{X}_{n}\notag.
\end{align*}
By transposing the above inequality, and note that 
\(y_{n}g(\theta_{n+1}) - y_{n}g(\theta_{n}) = y_{n+1}g(\theta_{n+1}) - y_{n}g(\theta_{n}) + (y_{n} - y_{n+1})g(\theta_{n+1}),\) we obtain
\begin{equation}\nonumber\begin{aligned}
\frac{\alpha_{0}}{4}y_{n}\zeta(n)&\le \big(y_{n}\hat{g}(\theta_{n})-y_{n+1}\hat{g}(\theta_{n+1})\big)+{(y_{n+1}-y_{n})\hat{g}(\theta_{n+1})}+C_{\Gamma, 1}\cdot y_{n}\Gamma_n\\&+C_{\Gamma,2}y_{n}\frac{\Gamma_{n}}{\sqrt{S_{n}}}+\alpha_0 y_{n}\hat{X}_{n}.
\end{aligned}\end{equation}
For any positive number \(T \ge 0\), we telescope the terms indexed by \(n\) from 1 to \(T\), and take the mathematical expectation, yielding
\begin{align}\label{ada_q_1}
\frac{\alpha_{0}}{4}\mathbb{E}\Bigg[\sum_{n=1}^{T}y_{n}\zeta_{n}\Bigg]&{\leq} y_{1}\hat{g}(\theta_{1})+\mathbb{E}\Bigg[\underbrace{\sum_{n=1}^{T}(y_{n+1}-y_{n})\hat{g}(\theta_{n+1})}_{\Theta_{1}}\Bigg]+C_{\Gamma,1}\cdot\underbrace{\sum_{n=1}^{T}y_{n}\Gamma_{n}}_{\Theta_{2}}+C_{\Gamma,2}\cdot\underbrace{\sum_{n=1}^{T}y_{n}\frac{\Gamma_{n}}{\sqrt{S_{n}}}}_{\Theta_{3}}+0.
\end{align}
Our objective is to prove that the RHS of the above inequality has an upper bound independent of $T.$ To this end, we bound $\Theta_{1}$, $\Theta_{2}$, and $\Theta_{3}$ separately. For $\Theta_{2}$, we have
\begin{align}\label{jh_02}
\Theta_{1}&=\sum_{n=1}^{T}(y_{n+1}-y_{n})\hat{g}(\theta_{n+1})=\sum_{n=1}^{T}\Big(\frac{1}{\sqrt{S_{n+1}}}-\frac{1}{\sqrt{S_{n}}}\Big)\hat{g}(\theta_{n+1})\le 0.
\end{align}
Then for term $\Theta_{2}$ in \cref{jh_02}, we have
\begin{align}\label{jh_03}
\Theta_{2}=\sum_{n=1}^{T}y_{n}\Gamma_{n}&\le \sum_{n=1}^{T}\frac{\Gamma_{n}}{\sqrt{S_{n-1}}}=\sum_{n=1}^{T}y_{n}\Gamma_{n}\le \sum_{n=1}^{T}\frac{\Gamma_{n}}{\sqrt{S_{n}}}+\sum_{n=1}^{T}\Gamma_{n}\bigg(\frac{1}{\sqrt{S_{n-1}}}-\frac{1}{\sqrt{S_{n}}}\bigg)\notag\\&\mathop{\le}^{(a)} \int_{S_{0}}^{+\infty}\frac{1}{x^{\frac{3}{2}}}\text{d}x+\frac{1}{\sqrt{S_{0}}}=\frac{3}{\sqrt{S_{0}}}.
\end{align}
In step $(a)$, we apply the series-integral inequality and the fact that \(\|\nabla g(\theta_{n})\|/\sqrt{S_{n}}\le 1.\)
Finally for term \(\Theta_{3}\), we only need to use the series-integral inequality to get
\begin{align}\label{jh_04}
\Theta_{3}=\sum_{n=1}^{T}y_{n}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\le \frac{1}{\sqrt{S_{0}}}\int_{S_{0}}^{+\infty}\le \frac{2}{S_{0}}.
\end{align}
Subsequently, we substitute the estimates for $\Theta_{1}$, $\Theta_{2},$ and $\Theta_{3}$ from \cref{jh_02}, \cref{jh_03}, and \cref{jh_04} back into \cref{ada_q_1}, resulting in the following inequality
\begin{align*}
\frac{\alpha_{0}}{4}\mathbb{E}\Bigg[\sum_{n=1}^{T}y_{n}\zeta_{n}\Bigg]&{\leq} y_{1}\hat{g}(\theta_{1})+0+\frac{3C_{\Gamma,1}}{\sqrt{S_{0}}}+\frac{2C_{\Gamma,2}}{S_{0}}<+\infty.
\end{align*}
The right-hand side of the above inequality is independent of \(T\). Therefore, by applying the \emph{ Lebesgue's monotone convergence} theorem, we obtain
\begin{align*}
\frac{\alpha_{0}}{4}\mathbb{E}\Bigg[\sum_{n=1}^{+\infty}y_{n}\zeta_{n}\Bigg]&{\leq} y_{1}\hat{g}(\theta_{1})+\frac{3C_{\Gamma,1}}{\sqrt{S_{0}}}+\frac{2C_{\Gamma,2}}{S_{0}}<+\infty.
\end{align*}
Then,
\begin{align*}
\mathbb{E}\Bigg[\sum_{n=1}^{+\infty}\frac{\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\Bigg]\le M:=\hat{g}(\theta_{1})+\frac{3C_{\Gamma,1}}{\sqrt{S_{0}}}+\frac{2C_{\Gamma,2}}{S_{0}}<+\infty,
\end{align*}
where $M$ is a constant. For any $\nu > 0$,
combined with the affine noise variance condition, we further achieve the subsequent inequality
\begin{align}
    \mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}> \nu}\mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\|^{2}|\mathscr{F}_{n-1}]&\le \mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\nu}( {\sigma_{0}}\|\nabla g(\theta_{n})\|^{2}+{\sigma_{1}})\notag\\&= \mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\nu}\Big({\sigma_{0}}+\frac{{\sigma_{1}}}{\|\nabla g(\theta_{n})\|^{2}}\Big)\|\nabla g(\theta_{n})\|^{2} \notag \\
    & <  \mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\nu}\Big({\sigma_{0}}+{\frac{\sigma_{1}}{{\nu}}}\Big)\cdot\|\nabla g(\theta_{n})\|^{2}\notag\\&\le \Big({\sigma_{0}}+{\frac{\sigma_{1}}{\nu}}\Big)\cdot\|\nabla g(\theta_{n})\|^{2}.
\end{align}
Then, we obtain
\begin{align*}
    \mathbb{E}\Bigg[ \sum_{n=1}^{+\infty}\mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\nu}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}}\Bigg]&\le\mathbb{E}\Bigg[ \sum_{n=1}^{+\infty}\mathbb{I}_{\|\nabla g(\theta_{n})\|^{2}>\nu}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n-1}}\Bigg]\notag\\&\le\Big({\sigma_{0}}+{\frac{\sigma_{1}}{\nu}}\Big)\cdot\mathbb{E}\Bigg[\sum_{n=1}^{+\infty}\frac{\|\nabla g(\theta_{n})\|^{2}}{S_{n-1}}\Bigg] \\&<\Big({\sigma_{0}}+{\frac{\sigma_{1}}{{\nu}}}\Big)\cdot M.
\end{align*}
This completes the proof.

(of \cref{lem:psi:i1})
We start by observing the inequality
\[\Psi_{i,1}=\mathbb{E}[\mathbb{I}_{\tau_{3i-1, T} < \tau_{3i, T}}]=\mathbb{P}(\tau_{3i-1, T} < \tau_{3i, T}).\]
What we need to consider is the probability of the event $\tau_{3i-1, T} < \tau_{3i, T}$ occurring. In the case we consider $\tau_{3i-1, T} < \tau_{3i, T}$ which implies that $\hat{g}(\theta_{3i-1, T}) \geq 2\Delta_0$. On the other hand, according to the definition of the stopping time $\tau_{3i-2,T}$, we have $\hat{g}(\tau_{{3i-2, T}-1}) \leq \Delta_0$. Then
\begin{align*}
\hat{g}(\theta_{\tau_{3i-2,T}}) <  \hat{g}(\theta_{\tau_{3i-2,T}-1})+h(\hat{g}(\theta_{\tau_{3i-2,T}-1})) \leq \Delta_0 + h(\Delta_0) < \frac{3}{2}\Delta_0.
\end{align*}
Since \(\Delta_0 > C_{0}\), we know that \( h(\Delta_0) < \frac{1}{2}\Delta_0\) by \cref{lem:adj:ghat}.  Then, by \cref{sufficient:lem}),
\begin{align*}
\frac{\Delta_0}{2} &=2\Delta_0-\frac{3\Delta_0}{2}\le \hat{g}(\theta_{\tau_{3i-1,T}})-\hat{g}(\theta_{\tau_{3i-2,T}})\le \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}(\hat{g}(\theta_{n+1})-\hat{g}(\theta_{n}))\\&\le C_{\Gamma,1}\cdot \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\Gamma_n  +C_{\Gamma,2}\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}} + \alpha_0\Bigg| \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}\Bigg|\\& \mathop{\le}^{\text{Young's inequality}} C_{\Gamma,1}\cdot \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\Gamma_n  +C_{\Gamma,2}\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}+\frac{\alpha_0^{2}}{\Delta_0}\Bigg( \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}\Bigg)^{2}  + \frac{\Delta_0}{4},
\end{align*} 
which further induces that 
\begin{equation}\label{power_00}\begin{aligned}
\frac{\Delta_0}{4}&\le  C_{\Gamma,1}\cdot \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\Gamma_n  +C_{\Gamma,2}\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}  + \frac{\alpha_0^{2}}{\Delta_0}\Bigg( \sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}\Bigg)^{2}.
\end{aligned}\end{equation}
Based on the above analysis, we can obtain the following sequence of event inclusions
\begin{align*}
\{\tau_{3i-1,T}<\tau_{3i,T}\}&\subset \{\hat{g}(\theta_{3i-1,T})>2\Delta_{0}\}\subset\Big\{\frac{\Delta_{0}}{2}\le \hat{g}(\theta_{\tau_{3i-1,T}})-\hat{g}(\theta_{\tau_{3i-2,T}})\Big\}\\&\subset\{\text{\cref{power_00} holds}\}.
\end{align*}
Thus, we have the following probability inequality
\begin{align*}
\mathbb{E}[\mathbb{I}_{\tau_{3i-1,T}<\tau_{3i,T}}]=\mathbb{P}(\tau_{3i-1,T}<\tau_{3i,T})\le \mathbb{P}(\text{\cref{power_00} holds}).
\end{align*}
Then, according to \emph{Markov's inequality}, we obtain
\begin{align*}
\mathbb{P}(\text{\cref{power_00} holds})&\le \frac{4}{\Delta_0}C_{\Gamma,1}\cdot \mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\Gamma_n\Bigg]  \\&+ \frac{4C_{\Gamma,2}}{\Delta_0}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]  + \frac{4\alpha_0^{2}}{\Delta_0^{2}}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}\Bigg]^{2}\\&\mathop{=}^{\text{\cref{sum:expect:ab}}} \frac{4C_{\Gamma,1}}{\Delta_0}\cdot \mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\mathbb{E}[\Gamma_n|\mathscr{F}_{n-1}]\Bigg]  + \frac{4C_{\Gamma,2}}{\Delta_0}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\frac{\Gamma_{n}}{\sqrt{S_{n}}}\Bigg]\\&  + \frac{4\alpha_0^{2}}{\Delta_0^{2}}\mathbb{E}\Bigg[\sum_{n=\tau_{3i-2,T}}^{\tau_{3i-1,T}-1}\hat{X}_{n}^{2}\bigg].
\end{align*}
This completes the proof.

(of \cref{step size})
Firstly, when $\lim_{n\rightarrow+\infty}S_{n} < +\infty,$ we clearly have \[\sum_{n=1}^{+\infty}\frac{1}{\sqrt{S_{n}}} = +\infty.\] We then only need to prove that this result also holds for the case $\lim_{n\rightarrow+\infty}S_{n} = +\infty.$ That is, we define the event $S$ \[\mathcal{S} := \left\{\sum_{n=1}^{+\infty}\frac{1}{\sqrt{S_{n}}} < +\infty,\ \text{and}\ \lim_{n\rightarrow+\infty}S_{n}=+\infty\right\}\] and desire to prove that \(\mathbb{P}(\mathcal{S}) = 0.\) 

According to the stability of $g(\theta_n)$ in \cref{stable}, the following result holds almost surely on the event $\mathcal{S}$.
\begin{equation}\label{wxm_03}\begin{aligned}
\sum_{n=1}^{+\infty}\frac{\|\nabla g(\theta_{n+1})\|^{2}}{\sqrt{S_{n}}} \mathop{\leq}^{\text{\cref{loss_bound}}} 2 L\Big(\sup_{n\ge 1}g(\theta_{n})\Big)\cdot\sum_{n=1}^{+\infty}\frac{1}{\sqrt{S_{n}}}<+\infty\ \text{a.s.}
\end{aligned}\end{equation}
On the other hand, by the affine noise variance condition  \( \mathbb{E}\big[\|\nabla g(\theta_{n+1};\xi_{n+1})\|^{2} \big| \mathscr{F}_{n}\big] \leq \sigma_0\|\nabla g(\theta_{n+1})\|^{2} + \sigma_{1}\), it induces that 
\begin{align}\label{inequ:sum:gradS}
\sum_{n=1}^{+\infty}\frac{\|\nabla g(\theta_{n+1})\|^{2}}{\sqrt{S_{n}}}&\ge \frac{1}{\sigma_{0}}\sum_{n=1}^{+\infty}\frac{\mathbb{E}[\|\nabla g(\theta_{n+1},\xi_{n+1})\|^{2}|\mathscr{F}_{n}]}{\sqrt{S_{n}}}-\sum_{n=1}^{+\infty}\frac{\sigma_{1}}{\sigma_{0}\sqrt{S_{n}}} \notag \\ &=\frac{1}{\sigma_{0}}\underbrace{\sum_{n=1}^{+\infty}\frac{\|\nabla g(\theta_{n+1},\xi_{n+1})\|^{2}}{\sqrt{S_{n}}}}_{\Xi_1}-\underbrace{\sum_{n=1}^{+\infty}\frac{\sigma_{1}}{\sigma_{0}\sqrt{S_{n}}}}_{\Xi_2} \notag \\&+\underbrace{\sum_{n=1}^{+\infty}\frac{\mathbb{E}[\|\nabla g(\theta_{n+1},\xi_{n+1})\|^{2}|\mathscr{F}_{n}]-\|\nabla g(\theta_{n+1},\xi_{n+1})\|^{2}}{\sqrt{S_{n}}}}_{\Xi_3}.
\end{align}
Next, we determine whether the RHS of \cref{inequ:sum:gradS} converges the event $\mathcal{S}.$ For the term $\Xi_1$, using the series-integral comparison test, the following result holds on the event $\mathcal{S}$:
\[\Xi_1 = \lim_{n \rightarrow \infty} \int_{S_{0}}^{S_{n}}\frac{1}{\sqrt{x}}\text{d}x = \lim_{n \rightarrow \infty}\sqrt{S_n} - \sqrt{S_0}=+\infty.\] The second term $\Xi_2$ clearly converges on $\mathcal{S}.$ Since the last term $\Xi_3$ is the sum of a martingale sequence, we only need to determine the convergence of the following series on the set $\mathcal{S}$
\begin{align*}
&\sum_{n=1}^{+\infty}\mathbb{E}\Bigg[\bigg|\frac{\|\nabla g(\theta_{n+1},\xi_{n+1})\|^{2}-\mathbb{E}[\|\nabla g(\theta_{n+1},\xi_{n+1})\|^{2}|\mathscr{F}_{n}]}{\sqrt{S_{n}}}\bigg| \mid \mathscr{F}_{n}\Bigg]\\ 
& \leq 2\sum_{n=1}^{+\infty}\mathbb{E}\Bigg[\frac{\|\nabla g(\theta_{n+1},\xi_{n+1})\|^{2}}{\sqrt{S_{n}}} \mid \mathscr{F}_{n}\Bigg]  \mathop{<}^{(a)}2(2 L\sigma_{0}\sup_{n\ge 1}g(\theta_{n})+\sigma_{1})\sum_{n=1}^{+\infty}\frac{1}{\sqrt{S_{n}}}<+\infty\  \,\, a.s.,
\end{align*}
where $(a)$ uses the affine noise variance condition $\mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\|^{2}|\mathscr{F}_{n-1}]\le \sigma_{0}\|\nabla g(\theta_{n})\|^{2}+\sigma_{1},$ and \cref{loss_bound} that $ \|\nabla g(\theta)\|^{2}\le 2 Lg(\theta) $ for $\forall\ \theta\in\mathbb{R}^{d}.$
We conclude that the last term $\Xi_3$ converges almost surely. Therefore, combining the above estimations for $\Xi_1, \Xi_2, \Xi_3$, we prove that the following relation holds on the event $\mathcal{S}$: \[\sum_{n=1}^{+\infty}\frac{\|\nabla g(\theta_{n+1})\|^{2}}{\sqrt{S_{n}}}=+\infty\ \text{a.s.}\] 
However, in \cref{wxm_03} we know that the series $\sum_{n=1}^{+\infty}\frac{\|\nabla g(\theta_{n+1})\|^{2}}{\sqrt{S_{n}}}$ converges almost surely on the event $\mathcal{S}$. Thus, we can claim that if and only if the event $\mathcal{S}$ is a set of measure zero, that is $\mathbb{P}(\mathcal{S}) = 0.$ We complete the proof.

(of \cref{lem8})
Recalling the sufficient decrease inequality in \cref{sufficient:lem}, we have
\begin{align*}
\hat{g}(\theta_{n+1})-\hat{g}(\theta_{n}) & \le -\frac{\alpha_{0}}{4}\zeta(n)+C_{\Gamma,1}\cdot \Gamma_n  +C_{\Gamma,2}\frac{\Gamma_{n}}{\sqrt{S_{n}}} + \alpha_0 \hat{X}_{n}.
\end{align*}
We take the mathematical expectation
\begin{align}\label{12sqdr}
\mathbb{E}\big[\hat{g}(\theta_{n+1})\big]-\mathbb{E}\big[\hat{g}(\theta_{n})\big] &  \le -\frac{\alpha_{0}}{4}\mathbb{E}\left[\zeta(n)\right]+C_{\Gamma,1}\cdot \mathbb{E}\left[\Gamma_n \right]+C_{\Gamma,2}\mathbb{E}\left[\frac{\Gamma_{n}}{\sqrt{S_{n}}} \right] + \alpha_0 \mathbb{E}\left[\hat{X}_{n},
\right]\end{align}
since $\hat{X}_{n}$ is a martingale such that $\mathbb{E}\left[\hat{X}_{n} \mid \mathscr{F}_{n-1}\right] = 0$. Telescoping the above inequality from $n=1$ to $T$ gives
\begin{align}\label{jrn_1}
\sum_{n=1}^{T}\mathbb{E}\left[\zeta(n)\right] & \le \frac{4}{\alpha_0}\mathbb{E}\big[\hat{g}(\theta_{1})\big]+\frac{4C_{\Gamma,1}}{\alpha_0}\sum_{n=1}^{T}\mathbb{E}\left[\Gamma_n \right] + \frac{4C_{\Gamma,2}}{\alpha_0}\sum_{n=1}^{T}\mathbb{E}\left[\frac{\Gamma_{n}}{\sqrt{S_{n}}} \right].
\end{align}
Note that \begin{align}
& \sum_{n=1}^{T} \mathbb{E}\left[\Gamma_n \right]  =  \mathbb{E}\left[\sum_{n=1}^{T} \frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}} \right] \leq \mathbb{E}\left[\int_{S_{0}}^{S_{T}}\frac{1}{x}\text{d}x \right]\leq \mathbb{E}\left[\ln (S_T/S_0)\right] \leq \mathbb{E}(\ln S_T) - \ln S_0 \notag \\
& \mathbb{E}\bigg[\sum_{n=1}^{T}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}^{\frac{3}{2}}}\bigg] \leq \mathbb{E}\left[\int_{S_{0}}^{S_T} \frac{1}{x^{\frac{3}{2}}} \mathrm{d} x \right] \le \frac{2}{\sqrt{S_{0}}}<+\infty. \notag
\end{align}
Substituting the above results into \cref{jrn_1}, we have
\begin{align}\label{inqu:lem:v1:1}
\sum_{n=1}^{T}\mathbb{E}\left[\zeta(n)\right] & \le \left(\frac{4}{\alpha_0}\mathbb{E}\big[\hat{g}(\theta_{1})\big] -\frac{4C_{\Gamma,1}}{\alpha_0}\ln S_0  \right)+ \frac{4C_{\Gamma,1}}{\alpha_0}\mathbb{E}\left[\ln S_T \right] + \frac{4C_{\Gamma,2}}{\alpha_0}\frac{2}{\sqrt{S_0}}.
\end{align}
By \cref{lem_S_{T}} (b), we know that $$S_T \leq \left(\sum_{n=1}^{\infty}\frac{\zeta(n)}{n^{2}} + \sqrt{S_0} \right)^2T^4.$$
Combing \cref{lem_S_{T}} (a), we have 
\begin{align}
\mathbb{E}\left[\ln S_T \right] & \leq 2\mathbb{E}\left[\sum_{n=1}^{\infty}\frac{\zeta(n)}{n^{2}} + \sqrt{S_0}\right] + 4\ln T = 2 \sum_{n=1}^{\infty}\frac{\mathbb{E}\left[\zeta(n)\right]}{n^{2}} + 4\ln T + 2\sqrt{S_0} \notag \\
&  \leq 4\ln T + \mathcal{O}(1). \notag
\end{align}
Then for any $T \geq 1$
\begin{equation}\nonumber\begin{aligned}
\sum_{n=1}^{T}\mathbb{E}\left[\zeta(n)\right] & \le  \frac{16C_{\Gamma,1}}{\alpha_0}  \ln T  + \mathcal{O}(1).
\end{aligned}\end{equation}
The proof is complete.

(of \cref{lem23})
Applying the $ L$-smoothness of $g$ and the iterative formula of AdaGrad-Norm, we have 
\begin{align}\label{inequ:smoothness:g}
g(\theta_{n+1}) \leq g(\theta_n)- \alpha_0 \frac{\nabla g(\theta_n)^{T}\nabla g(\theta_n,\xi_n)}{\sqrt{S_n}} + \frac{ L\alpha_0^2}{2}\frac{\nabla g(\theta_n; \xi_n)^2}{S_n}.
\end{align}
Then combined with $g^{2}(\theta_{n+1})-g^{2}(\theta_{n}) = \left(g(\theta_{n+1})-g(\theta_{n}) \right)\left(g(\theta_{n+1})+g(\theta_{n}) \right)$ we have
\begin{align}\label{inequ:sufifient:v2:1}
& \quad g^{2}(\theta_{n+1})-g^{2}(\theta_{n}) \notag \\ &\le -\frac{2\alpha_{0}g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})}{\sqrt{S_{n}}}+ \frac{\alpha_0^2\left(\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\right)^2}{S_n} \notag 
\\& \quad +\left(g(\theta_{n}) - \frac{\alpha_0\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})}{\sqrt{S_{n}}}\right) L\alpha_{0}^{2}\frac{\big\|\nabla g(\theta_{n},\xi_{n})\big\|^{2}}{S_{n}} +  \frac{ L^2\alpha_0^4}{4}\frac{\big\|\nabla g(\theta_{n},\xi_{n})\big\|^{4}}{S_{n}^2}  \notag \\
& \mathop{\leq}^{(a)} -\frac{2\alpha_{0}g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})}{\sqrt{S_{n}}} + g(\theta_n)\left(2+\alpha_0^2 \right) L\cdot\Gamma_n   + \frac{\alpha_0^2}{2}\left\| \nabla g(\theta_n)\right\|^2\Gamma_n  + \frac{3\alpha_0^4 L^2}{4}\Gamma_n  \notag \\
& \leq -\frac{2\alpha_{0}g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})}{\sqrt{S_{n}}} + \left((2+2\alpha_0^2) Lg(\theta_n) + \frac{3\alpha_0^4 L^2}{4} \right)\Gamma_n 
\end{align} 
Here we inherit the notation $\Gamma_n = \left\|\nabla g(\theta_n, \xi_n) \right\|^2/S_n$ in \cref{inequ:sufficient:decrease}. For $(a)$ we use some common inequalities, the facts that  $S_n \geq \left\|\nabla g(\theta_{n},\xi_{n}) \right\|^2$, \cref{loss_bound} such that
\begin{align}
\frac{\left(\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\right)^2}{S_n} &  
\leq \frac{\left\|\nabla g(\theta_{n}) \right\|^2\left\|\nabla g(\theta_{n},\xi_{n}) \right\|^2}{S_n} \leq \frac{2 Lg(\theta_n)\left\|\nabla g(\theta_{n},\xi_{n}) \right\|^2}{S_n} \notag \\
- \frac{\alpha_0\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})}{\sqrt{S_{n}}} 
& \leq \frac{1}{2 L}\left\|\nabla g(\theta_{n})\right\|^2 + \frac{\alpha_0^2 L}{2} \frac{\left\|\nabla g(\theta_{n},\xi_{n}) \right\|^2}{S_n} \leq \frac{1}{2 L}\left\|\nabla g(\theta_{n})\right\|^2 + \frac{\alpha_0^2 L}{2}  \notag \\
\frac{\big\|\nabla g(\theta_{n},\xi_{n})\big\|^{4}}{S_{n}^2} &  \leq \frac{\big\|\nabla g(\theta_{n},\xi_{n})\big\|^{2}}{S_{n}}.
\end{align}
and for the last inequality we use \cref{loss_bound} that $\left\|\nabla g(\theta_n) \right\|^2 \leq 2 Lg(
\theta_n).$
For the first term of RHS of \cref{inequ:sufifient:v2:1}, we let $\Delta_{S, n}$ denote  $1/\sqrt{S_n} -1/\sqrt{S_{n-1}}$ and inherit the notation $\zeta(n) = \left\|\nabla g(\theta_{n})\right\|^2/\sqrt{S_{n-1}}$ in \cref{inequ:sufficient:decrease}:
\begin{align}\label{inqu:sufficient:v2:2}
&\frac{g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})}{\sqrt{S_{n}}}  = \frac{g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})}{\sqrt{S_{n-1}}} + g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\Delta_{S,n} \notag \\ 
& = g(\theta_{n}) \zeta(n)  + \frac{g(\theta_{n})\nabla g(\theta_{n})^{\top}\left( \nabla g(\theta_{n},\xi_{n})- g(\theta_{n})\right)}{\sqrt{S_{n-1}}} + g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\Delta_{S,n}.
\end{align}
We then substitute \cref{inqu:sufficient:v2:2} into \cref{inequ:sufifient:v2:1} and achieve that
\begin{align}\label{inequ:sufficient:v2:3}
g^{2}(\theta_{n+1})-g^{2}(\theta_{n}) 
&\le - 2\alpha_0 g(\theta_{n})\zeta(n) + \left((2+2\alpha_0^2) Lg(\theta_n) + \frac{3\alpha_0^4 L^2}{4} \right)\Gamma_n\notag \\
& + 2\alpha_0g(\theta_{n})\mathbb{E}\left[\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\Delta_{S,n} \mid \mathscr{F}_{n-1}\right] + 2\alpha_0\hat{Y}_n,
\end{align}
where $\hat{Y}_n$ is a martingale different sequence and defined below
\begin{equation}\nonumber\begin{aligned}
 \hat{Y}_n &:=\frac{g(\theta_{n})\nabla g(\theta_{n})^{\top}(\nabla g(\theta_{n})-\nabla g(\theta_{n},\xi_{n}))}{\sqrt{S_{n-1}}}\\&+g(\theta_{n})\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\Delta_{S, n}-g(\theta_{n})\mathbb{E}\bigg[\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\Delta_{S, n}\bigg|\mathscr{F}_{n-1}\bigg].\end{aligned}\end{equation}
For the second to last term of RHS of \cref{inequ:sufficient:v2:3} we have
\begin{equation}\nonumber\begin{aligned}
&\quad 2\alpha_{0}g(\theta_{n})\mathbb{E}\bigg[\nabla g(\theta_{n})^{\top}\nabla g(\theta_{n},\xi_{n})\Delta_{S,n}\bigg|\mathscr{F}_{n-1}\bigg]\\& \mathop{\le}^{(a)} \alpha_{0}g(\theta_{n})\|\nabla g(\theta_{n})\|^{2} \Delta_{S,n}+4\alpha_{0}g(\theta_{n})\mathbb{E}^{2}\bigg[\nabla g(\theta_{n},\xi_{n})\sqrt{\Delta_{S,n}}\bigg|\mathscr{F}_{n-1}\bigg] \notag \\
& \mathop{\le}^{(b)}\frac{\alpha_{0}g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}+4\alpha_{0}g(\theta_{n})\mathbb{E}[\|\nabla g(\theta_{n},\xi_{n})\|^{2}|\mathscr{F}_{n-1}]\cdot\mathbb{E}\bigg[\Delta_{S,n}\bigg|\mathscr{F}_{n-1}\bigg]\\&\mathop{\le}^{(c)} \frac{\alpha_{0}g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}+4\alpha_{0}g(\theta_{n})\mathbb{E}\bigg[(\sigma_{0}\|\nabla g(\theta_{n})\|^{2}+\sigma_{1})\Delta_{S,n}\bigg|\mathscr{F}_{n-1}\bigg]\\&\mathop{\le}^{(d)} \alpha_{0}g(\theta_{n})\zeta(n)+4 L\alpha_{0}\sigma_{0}g^{2}(\theta_{n})\mathbb{E}\bigg[ \Delta_{S,n}\bigg|\mathscr{F}_{n-1}\bigg]+4\alpha_{0}\sigma_{1}g(\theta_{n})\mathbb{E}\bigg[\Delta_{S,n}\bigg|\mathscr{F}_{n-1}\bigg],
\end{aligned}\end{equation} 
where $(a)$ follows from mean inequality, $(b)$ uses Cauchy-Schwartz inequality, $(c)$ applies the affine noise variance condition, and $(d)$ follows from \cref{loss_bound} which states $\|\nabla g(\theta)\|^2 \leq 2 Lg(\theta)$. We then substitute the above estimation into \cref{inequ:sufficient:v2:3}
\begin{align}\label{inequ:sufficient:key}
{g^{2}(\theta_{n+1})}-{g^{2}(\theta_{n})} 
& \le- \alpha_0 g(\theta_{n}) \zeta(n)+4 L\alpha_{0}\sigma_{0}g^{2}(\theta_{n})\mathbb{E}\left[\Delta_{S,n}\mid\mathscr{F}_{n-1}\right]+4\alpha_{0}\sigma_{1}g(\theta_{n})\mathbb{E}\left[\Delta_{S,n}\mid\mathscr{F}_{n-1}\right] \notag \\& +\left((2+2\alpha_0^2) Lg(\theta_n) + \frac{3\alpha_0^4 L^2}{4} \right)\Gamma_n +2\alpha_0 \hat{Y}_n.
\end{align}
Next, for any stopping time $\tau$ that satisfies $[\tau=i] \in \mathscr{F}_{i-1}\ (\forall\ i>0)$, telescoping the index $n$ from $1$ to $\tau\wedge T-1$ in \cref{inequ:sufficient:key} and taking expectation on the above inequality yields
\begin{equation}\label{jrn_4}\begin{aligned}
&\mathbb{E}\big[{g^{2}(\theta_{\tau\wedge T})}\big]-\mathbb{E}\big[{g^{2}(\theta_{1})}\big]\le- \alpha_0 \mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g(\theta_{n}) \zeta(n)\bigg]\\&+4 L\alpha_{0}\sigma_{0}\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g^{2}(\theta_{n})\mathbb{E}\bigg[\Delta_{S,n}\bigg|\mathscr{F}_{n-1}\bigg]\bigg]+4\alpha_{0}\sigma_{1}\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g(\theta_{n})\mathbb{E}\bigg[\Delta_{S,n}\bigg|\mathscr{F}_{n-1}\bigg]\bigg]\\&+\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\left((2+2\alpha_0^2) Lg(\theta_n) + \frac{3\alpha_0^4 L^2}{4} \right) \Gamma_n\bigg]+2\alpha_0\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1} \hat{Y}_n\bigg]. 
\end{aligned}\end{equation} 
We further use \emph{Doob's stopped} theorem that $\mathbb{E}\big[\sum_{n=1}^{\tau\wedge T-1}\mathbb{E}(\cdot|\mathscr{F}_{n-1})\big]=\mathbb{E}\big[\sum_{n=1}^{\tau\wedge T-1}\cdot\big]$ to simplify \cref{jrn_4} and achieve that 
\begin{align}\label{jrn_5}
& \quad \mathbb{E}\big[{g^{2}(\theta_{\tau\wedge T})}\big]-\mathbb{E}\big[{g^{2}(\theta_{1})}\big] \notag \\
&\le- \alpha_0 \mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g(\theta_{n}) \zeta(n)\bigg]+4 L\alpha_{0}\sigma_{0}\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g^{2}(\theta_{n})\Delta_{S,n}\bigg]+4\alpha_{0}\sigma_{1}\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g(\theta_{n})\Delta_{S,n}\bigg] \notag \\&\quad +\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\left((2+2\alpha_0^2) Lg(\theta_n) + \frac{3\alpha_0^4 L^2}{4} \right) \Gamma_n\bigg] + 0.
\end{align}
For the second term on the RHS of the aforementioned inequality, we have the following estimation
\begin{equation}\label{jrn_6}\begin{aligned}
&\quad \mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g^{2}(\theta_{n})\bigg(\Delta_{S, n}\bigg)\bigg] \notag \\
& =\mathbb{E}\bigg[\sum_{n=0}^{\tau\wedge T-2}\frac{g^{2}(\theta_{n+1})}{\sqrt{S_{n}}}-\sum_{n=1}^{\tau\wedge T-1}\frac{g^{2}(\theta_{n})}{\sqrt{S_{n}}}\bigg] \leq \mathbb{E}\bigg[\frac{g^{2}(\theta_{1})}{\sqrt{S_{0}}}\bigg]+\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\frac{g^{2}(\theta_{n+1})-g^{2}(\theta_{n})}{\sqrt{S_{n}}}\bigg]\\& \mathop{\le}^{(a)} \mathbb{E}\bigg(\frac{g^{2}(\theta_{1})}{\sqrt{S_{0}}}\bigg)+ 2\alpha_0\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\frac{g(\theta_{n})\|\nabla g(\theta_{n})\|\|\nabla g(\theta_{n},\xi_{n})\|}{S_{n}}\bigg] \\&\quad +\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\left((2+2\alpha_0^2) Lg(\theta_n) + \frac{3\alpha_0^4 L^2}{4} \right)\frac{\big\|\nabla g(\theta_{n},\xi_{n})\big\|^{2}}{S_{n}^{\frac{3}{2}}}\bigg]\\& \mathop{\le}^{(b)} \mathbb{E}\bigg[\frac{g^{2}(\theta_{1})}{\sqrt{S_{0}}}\bigg]+\frac{\alpha_{0}\psi_1}{4}\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\frac{g(\theta_{n})\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}\bigg]+\frac{4\alpha_0}{\psi_1} \mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\frac{g(\theta_{n})\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}^{\frac{3}{2}}}\bigg] \notag \\
& \quad +\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\left((2+2\alpha_0^2) Lg(\theta_n) + \frac{3\alpha_0^4 L^2}{4} \right)\frac{\big\|\nabla g(\theta_{n},\xi_{n})\big\|^{2}}{S_{n}^{\frac{3}{2}}}\bigg],
\end{aligned}\end{equation}
where for $(a)$ we use the upper bound of $g^2(\theta_{n+1}) - g^2(\theta_n)$ in \cref{inequ:sufifient:v2:1} and \emph{the Cauchy-Schwartz inequality}, and for $(b)$ we use \emph{Young inequality} and let $\psi_1 = \frac{1}{4 L\sigma_0\alpha_0}$. 
Similarly, we can estimate the third term on the RHS of \cref{jrn_5} as follows.
\begin{equation}\label{jrn_6:v1}\begin{aligned}
&\quad\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}g(\theta_{n})\bigg(\Delta_{S, n}\bigg)\bigg] \notag \\
& =\mathbb{E}\bigg[\sum_{n=0}^{\tau\wedge T-2}\frac{g(\theta_{n+1})}{\sqrt{S_{n}}}-\sum_{n=1}^{\tau\wedge T-1}\frac{g(\theta_{n})}{\sqrt{S_{n}}}\bigg] \leq \mathbb{E}\bigg[\frac{g(\theta_{1})}{\sqrt{S_{0}}}\bigg]+\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\frac{g(\theta_{n+1})-g(\theta_{n})}{\sqrt{S_{n}}}\bigg]\\& \mathop{\le}^{(a)} \mathbb{E}\bigg[\frac{g(\theta_{1})}{\sqrt{S_{0}}}\bigg]+ \alpha_0\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\frac{\|\nabla g(\theta_{n})\|\|\nabla g(\theta_{n},\xi_{n})\|}{S_{n}}\bigg] +\frac{\alpha_0^2 L}{2}\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge n-1}\frac{\big\|\nabla g(\theta_{n},\xi_{n})\big\|^{2}}{S_{n}^{\frac{3}{2}}}\bigg]\\& \mathop{\le}^{(b)} \mathbb{E}\bigg[\frac{g(\theta_{1})}{\sqrt{S_{0}}}\bigg]+\frac{\alpha_{0}\psi_2}{4}\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge n-1}\frac{\|\nabla g(\theta_{n})\|^{2}}{\sqrt{S_{n-1}}}\bigg]+\left(\frac{\alpha_0}{\psi_2}  + \frac{\alpha_0^2 L}{2}\right)\mathbb{E}\bigg[\sum_{n=1}^{\tau\wedge T-1}\frac{\|\nabla g(\theta_{n},\xi_{n})\|^{2}}{S_{n}^{\frac{3}{2}}}\bigg],
\end{aligned}\end{equation}
where for $(a)$ we use \cref{inequ:smoothness:g} and \emph{the Cauchy-Schwartz inequality} and for $(b)$ we use \emph{Young inequality} and let $\psi_2 = 1/(4\alpha_0\sigma_1)$. 
Substituting the above estimations into \cref{jrn_5} we have
\begin{align}\label{jrn_8}
