& \le \left(2 L\sigma_{0}\sup_{t\ge 1}g(\theta_{t})+\sigma_{1}d\right)\cdot   \sum_{t=1}^{+\infty}\frac{1}{(t+1)\ln^{2}(t+1)} \mathop{<}^{\text{ \cref{bound''}}}+\infty\ \ \text{a.s.},
