where $\sum_{t=1}^{+\infty}\frac{1}{(t+1)\ln^{2}(t+1)} < \int_{2}^{\infty} \ln^{-2}(x)d( \ln x) < + \infty$.
By applying the \emph{Supermartingale Convergence} theorem, we deduce that the sequence \(\{\Sigma_{v_{t+1}}/\ln^{2}(t+1)\}_{t\ge 1}\) converges almost surely, which implies that
$\sup_{t\ge 1}\left(\frac{\Sigma_{v_{t}}}{\ln^{2}(t+1)}\right)<+\infty\ \ \text{a.s.}$




\begin{lem}\label{RMSProp_9}
    Under \cref{ass_g_poi} \ref{ass_g_poi:i}$\sim$\ref{ass_g_poi:i2}, \cref{ass_noise} \ref{ass_noise:i}, \cref{coordinate} \ref{coordinate_i_1}, consider RMSProp. We have
\[\sum_{t=1}^{T}\sum_{i=1}^{d}\frac{(\nabla_{i}g(\theta_{t}))^{2}}{t^{\frac{1}{2}+\delta}\ln(t+1)}<+\infty\ \ \text{a.s.} \,\, \text{where} \,\,  0<\delta\le 1/2. \]
\end{lem}
\begin{proof}
According to  \cref{RMSProp_0}, for any $0<\delta\le 1/2,$ we have 
\begin{align*}
\sum_{t=1}^{T}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\zeta_{i}(t)}{t^{\delta}}\right]=\mathcal{O}\left(\frac{1}{\delta}\right) .  
\end{align*}
Applying the \emph{Lebesgue's Monotone Convergence} theorem, we have
\begin{align*}
\sum_{t=1}^{T}\sum_{i=1}^{d}\frac{\zeta_{i}(t)}{t^{\delta}}<+\infty\ \ \text{a.s.}.  \end{align*}
Recalling that $\zeta_{i}(t) = (\nabla_i g(\theta_t))^2 \eta_{t-1,i} \geq (\nabla_i g(\theta_t))^2 \eta_{t,i}$ (by \cref{property_0}) and $\eta_{t,i} = \alpha_t / (\sqrt{v_{t,i}} + \epsilon)$, we have
\begin{align*}
\sum_{t=1}^{T}\sum_{i=1}^{d}\frac{\zeta_{i}(t)}{t^{\delta}} \geq  \sum_{t=1}^{T}\sum_{i=1}^{d}\frac{1}{t^{\frac{1}{2}+\delta}}\frac{(\nabla_{i}g(\theta_{t}))^{2}}{\sqrt{v_{t,i}}+\epsilon}\mathop{\ge}^{\text{\cref{bounded_v}}}\mathcal{O}\left( \sum_{t=1}^{T}\sum_{i=1}^{d}\frac{(\nabla_{i}g(\theta_{t}))^{2}}{t^{\frac{1}{2}+\delta}\ln(t+1)}\right)  ,
\end{align*}
where by \text{\cref{bounded_v}}, we have $v_{t,i} \leq \Sigma_{v_t} \leq \sup_{t} \Sigma_{v_t} \leq \mathcal{O}(\ln^2(t+1)) $.

\end{proof}
\begin{lem}\label{convergence_v}
