\begin{proof}
Recalling the recursive formula for \(v_t\), we have
\begin{align*}
   v_{t+1,i}\le v_{t,i}+\frac{1}{t+1}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} = v_{t,i}+\frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}<D_{0}]}}{t+1}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} +\frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}}{t+1}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}.
\end{align*}
Next, we examine the sum of the two series
\begin{align*}
 \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}<D_{0}]}}{(t+1)^{2}}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{4} |\mathscr{F}_{t-1}\right],\ \ \text{and}\ \  \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}}{t+1}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}|\mathscr{F}_{t-1}\right] .
\end{align*}
For the first series, based on \cref{coordinate}~\ref{coordinate_i_2}, it concludes
\begin{align*}
 \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}<D_{0}]}}{(t+1)^{2}}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{4} |\mathscr{F}_{t-1}\right]&<D_{1}^{2}  \sum_{t=1}^{+\infty}  \frac{1}{(t+1)^{2}}<+\infty\ \ \text{a.s.}
\end{align*}
We apply the coordinate-wise affine noise variance condition when $\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}$  and achieve that $\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} |\mathscr{F}_{t-1}\right] \leq \left(\sigma_0 \nabla_{i}g(\theta_{t}))^{2}  + \sigma_1 \right) \leq (\sigma_{0}+\frac{\sigma_{1}}{D_{0}})\nabla_{i}g(\theta_{t}))^{2}$ for any $\ i$. For the second series, 
\begin{align*}
 \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}}{t+1}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} |\mathscr{F}_{t-1}\right]&<\left(\sigma_{0}+\frac{\sigma_{1}}{D_{0}}\right)  \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}(\nabla_{i}g(\theta_{t}))^{2}}{(t+1)^{2}}\\& \leq \mathcal{O}\left(\sum_{t=1}^{+\infty}  \sum_{i=1}^{d}\frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}(\nabla_{i}g(\theta_{t}))^{2}}{t\ln(t+1)}\right)\\&\mathop{<}^{\text{ \cref{RMSProp_9} with $\delta=1/2$}}+\infty \ \ \text{a.s.}.
\end{align*}
According to the martingale convergence theorem, we have \(\{v_{t,i}\}_{t \geq 1}\) converges almost surely. Repeating the above procedure for each component \(i\), we conclude that all coordinate components converge almost surely which implies that \(\{v_{n}\}_{n \geq 1}\) converges almost surely. 







\end{proof}

\subsection{The Proof of \cref{bound''}}\label{stability:proof:rmsprop}
The main proof of \cref{bound''} for RMSProp is similar to the proof of AdaGrad. To maintain conciseness, we will use \(\mathcal{O}\) to simplify the relevant constant terms and will omit some straightforward calculations. We first present the following lemmas, \cref{lem:adj:ghat''} and \cref{dsad}, for RMSProp. The proofs of these lemmas are omitted, because they are straightforward and follow the same arguments as the corresponding lemmas, \cref{lem:adj:ghat} and \cref{pro_0}, for AdaGrad-Norm.
\begin{lem}\label{lem:adj:ghat''}
For the Lyapunov function $\hat{g}(\theta_n),$ there is a constant $C_0$ such that for any $\hat{g}(\theta_{n}) \geq C_0$, we have
$$\hat{g}(\theta_{n+1})-\hat{g}(\theta_{n})\leq \hat{g}(\theta_{n})/2.
$$ 
\end{lem}
\begin{property}\label{dsad}
Under~\cref{coordinate_0,coordinate}, the gradient sublevel set $J_{\eta}:=\bigcup_{i=1}^{d}\{\theta \mid (\nabla_{i} g(\theta))^{2}\le \eta\}$ with $\eta >0$ is a closed bounded set. Then, by~\cref{coordinate_0,coordinate}, there exist a constant $\hat{C}_{g} > 0$  such that the function  $\hat{g}(\theta) < \hat{C}_{g}$ for any $\theta \in J_{\eta}$. 
\end{property}


\begin{proof}(of \cref{bound''}) 
First, we define \(\Delta_{0} := \max\{C_{0}, 2\hat{g}(\theta_{1}), \hat{C}_{g}\}\). Based on the value of \(\hat{g}(\theta_{n})\) with respect to \(\Delta_{0}\), we define the following stopping time sequence $\{\tau_{n}\}_{n\ge 1}$
\begin{align}\label{stopping_time'}
&\tau_{1}:=\min\{k\ge 1:\hat{g}(\theta_{k})>\Delta_0\},\ \tau_{2}:=\min\{k\ge \tau_{1}: \hat{g}(\theta_{k})\le  \Delta_0\ \text{or}\ \hat{g}(\theta_{k})>2\Delta_0\},\notag\\&\tau_{3}:=\min\{k\ge \tau_{2}:\hat{g}(\theta_{k})\le \Delta_0\},...,
\notag\\&\tau_{3j-2}:=\min\{k> \tau_{3j-3}:\hat{g}(\theta_{k})>\Delta_0\},\ \tau_{3j-1}:=\min\{k\ge \tau_{3j-2}:\hat{g}(\theta_{k})\le  \Delta_0\ \text{or}\ \hat{g}(\theta_{k})>2\Delta_0\},\notag\\&\tau_{3j}:=\min\{k\ge  \tau_{3j-1}:\hat{g}(\theta_{k})\le  \Delta_0\}.
\end{align}
By the definition of \(\Delta_{0}\), we have \(\Delta_{0} > \hat{g}(\theta_{1})\), which asserts \(\tau_{1} > 1\). Since \(\Delta_{0} > C_{0}\), for any \(j\), we have \(\hat{g}(\theta_{\tau_{3j-2}}) < \Delta_{0} + \frac{\Delta_{0}}{2} < 2\Delta_{0}\), which asserts \(\tau_{3j-1} > \tau_{3j-2}\). For any \(T\) and \(n\), we define the truncated stopping time \(\tau_{n,T} := \tau_{n} \wedge T\). Then, based on the segments by the stopping time $\tau_{n, T}$, we estimate \(\mathbb{E}\left[\sup_{1 \leq n < T} \hat{g}(\theta_{n})\right]\) as follows.
\begin{align}\label{RMSprop_7}
   \mathbb{E}\left[\sup_{1\le n<T}\hat{g}(\theta_{n})\right]&\le \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-2,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right] +\mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j,T}\le n<\tau_{3j+1,T}}\hat{g}(\theta_{n})\right)\right]\notag\\&\le \Delta_{0}+ \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-2,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]\notag\\&\le \Delta_{0}+  \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-2,T}\le n<\tau_{3j-1,T}}\hat{g}(\theta_{n})\right)\right]+ \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]\notag\\&\le 3\Delta_{0}+ \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right].
\end{align}
Next, we proceed to estimate \(\mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]\).
\begin{align}\label{RMSprop_5}
 \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]& \mathop{\le}^{\text{\cref{lem:adj:ghat''}}}  3\Delta_{0}+  \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\left(\hat{g}(\theta_{n})-\hat{g}(\theta_{\tau_{3j-1,T}})\right)\right)\right]\notag\\&\le 3\Delta_{0}+  \mathbb{E}\left[\sup_{j\ge 1}\left(\sum_{t=\tau_{3j-1,T}}^{\tau_{3j,T}-1}\left|\hat{g}(\theta_{t+1})-\hat{g}(\theta_{t})\right|\right)\right]\notag\\& \mathop{\le}^{(a)} \mathcal{O}(1)+\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1,T}}^{\tau_{3j,T}-1}\sum_{i=1}^{d}\zeta_{i}(t)\right]\right),
\end{align}
where we follow the same procedure as \cref{inqu:diff:g:tau2} to derive the inequality $(a)$. The constant hidden within the \(\mathcal{O}\) notation is independent of \(T\). Applying the sufficient descent inequality in \cref{sufficient:lem'}, the last term of RHS of \cref{RMSprop_5} is bounded by
\begin{align}\label{RMSprop_6}
\quad & \leq \sum_{j=1}^{+\infty}\mathbb{E}\left[\hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j,T}})\right]+\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1},T}^{\tau_{3j,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right] \notag \\
& \quad +\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1},T}^{\tau_{3j,T}-1}M_{t}\right]\notag\\&=\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\right)+\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1},T}^{\tau_{3j,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]\right)+0\notag\\&\mathop{\le}^{(a)}\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\right)+\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1,T}}^{\tau_{3j,T}-1}\sum_{i=1}^{d}\frac{\zeta_{i}(t)}{\sqrt{t}}\right]\right)\notag\\&\mathop{\le}^{\text{ \cref{RMSProp_0}}}\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\right)+\mathcal{O}\left(1\right).   
\end{align}

Similar to the proof of ~\cref{lem:psi:i1}, the following inclusions of the events hold
\begin{align*}
\{\tau_{3j-1,T}<\tau_{3j,T}\}&\subset \{\hat{g}(\theta_{3i-1,T})>2\Delta_{0}\}\subset\left\{\frac{\Delta_{0}}{2}\le \hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j-2,T}})\right\}.
\end{align*}
To estimate \(\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\), we evaluate the probability of the event \(W=\left\{\frac{\Delta_{0}}{2}\le \hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j-2,T}})\right\}.\) Note that when the event $W$ occurs 
\begin{align*}
    \frac{\Delta_{0}}{2}&\le \hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j-2,T}}) \mathop{\le}^{\text{ \cref{sufficient:lem'}}}\left({ L}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}+\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\\&\mathop{\le}^{\text{\emph{AM-GM} inequality}}\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}+\frac{\Delta_{0}}{4}+\frac{1}{\Delta_{0}}\left(\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\right)^{2},
\end{align*}
which implies that the following inequality holds
\begin{align}\label{RMSprop_2}
    \frac{\Delta_{0}}{4}&\le\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}+\frac{1}{\Delta_{0}}\left(\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\right)^{2}.
\end{align}
Combining the above derivations, when the event \(\{\tau_{3j-1,T}<\tau_{3j,T}\}\) occurs, the event \(\{\text{\cref{RMSprop_2} holds}\}\) also occurs, which implies that
\begin{align}\label{RMSProp_2}
&\quad \mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right] \notag \\
& \le\mathbb{P}\left[\{\text{\cref{RMSprop_2} holds}\}\right]\notag\\&\mathop{\le}^{\text{\emph{Markov's} inequality}}\frac{4}{\Delta_{0}}\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]+\frac{4}{\Delta_{0}^{2}}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\right]^{2}\notag\\&\mathop{\le}^{\text{\emph{Doob's Stopped} theorem}}\frac{4}{\Delta_{0}}\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\underbrace{\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]}_{A_{j,1}}+\frac{4}{\Delta_{0}^{2}}\underbrace{\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M^{2}_{t}\right]}_{A_{j,2}}.
\end{align}
For \(A_{j,1}\), we further estimate it as follows.
\begin{align*}
A_{j,1}&=\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]\mathop{=}^{\text{\emph{Doob's Stopped} theorem}}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\mathbb{E}\left[\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}|\mathscr{F}_{t-1}\right]\right]\\&\le\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\mathbb{E}\left[\eta^{2}_{{t},i}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}|\mathscr{F}_{t-1}\right]\right] \notag \\
& \mathop{\le}^{\eta_{t,i}\le \frac{1}{\epsilon\sqrt{t}}}\frac{1}{\epsilon}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\eta_{t,i}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}}{\sqrt{t}}\bigg|\mathscr{F}_{t-1}\right]\right]\\&\mathop{\le}^{\text{\cref{property_0}}}\frac{1}{\epsilon}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}\bigg|\mathscr{F}_{t-1}\right]\right] \notag \\

&\mathop{\le}^{(a)}\frac{1}{\epsilon}\left(\sigma_{0}+\frac{\sigma_{1}}{\eta}\right)\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right].
\end{align*}
In \((a)\), if the stopping times \(\tau_{3j-2,T} = \tau_{3j-1,T}\), we define the sum \(\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1} = 0\), so it holds trivially. When \(\tau_{3j-2,T} < \tau_{3j-1,T}\), we know $\hat{g}(\theta_t) \in (\Delta_0, 2\Delta_0]$ where $\Delta_0 > \hat{C}_g$ for any \(t \in [\tau_{3j-2,T}, \tau_{3j-1,T})\). By \cref{{dsad}}, we have \((\nabla_{i}g(\theta_{t}))^{2} > \eta\) for any \(t \in [\tau_{3j-2,T}, \tau_{3j-1,T})\)  and $i \in [d]$. By the coordinated affine noise variance condition, we have \[\mathbb{E}\left[(\nabla_{i}g(\theta_{t}, \xi_{t}))^{2} \mid \mathscr{F}_{t-1}\right] \leq \sigma_{0}(\nabla_{i}g(\theta_{t}))^{2} + \sigma_{1} \leq \left(\sigma_{0} + \frac{\sigma_{1}}{\eta}\right)(\nabla_{i}g(\theta_{t}))^{2}.\]
We further show that $ \sum_{j=1}^{+\infty}A_{j,1}$ is uniformly bounded. In fact,
\begin{align*}
    \sum_{j=1}^{+\infty}A_{j,1}&\le \frac{1}{\epsilon}\left(\sigma_{0}+\frac{\sigma_{1}}{\eta}\right)\mathbb{E}\left[\sum_{j=1}^{+\infty}\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right] \leq \mathcal{O}\left(\sum_{t=1}^{+\infty}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right)\\&\mathop{\le}^{\text{\cref{RMSProp_0} with $\delta=1/2$}}\mathcal{O}(1).
\end{align*}
Then, following the same procedure as $A_{j,1}$ to estimate \(A_{j,2}\), we obtain that
\begin{align*}
 \sum_{j=1}^{+\infty}A_{j,2}\le \mathcal{O}\left(\sum_{t=1}^{+\infty}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right)\mathop{\le}^{\text{\cref{RMSProp_0} with $\delta=1/2$}}\mathcal{O}(1).  
\end{align*}
According to \cref{RMSprop_2}, combining the estimates for $A_{j,1}$ and $A_{j,2}$ gives
\begin{align*}
\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\le \mathcal{O}\left(\sum_{j=1}^{+\infty}A_{j,1}\right)+\mathcal{O}\left(\sum_{j=1}^{+\infty}A_{j,2}\right)\le \mathcal{O}(1).
\end{align*}
Substituting the above estimate into \cref{RMSprop_6}, and then into \cref{RMSprop_5} and \cref{RMSprop_7}, we obtain
\begin{align*}
\mathbb{E}\left[\sup_{1\le n<T}\hat{g}(\theta_{n})\right]  \le \mathcal{O}(1).
\end{align*}
where the constant hidden in \(\mathcal{O}\) is independent of \(T\). Taking \(T \to +\infty\) and applying the \emph{Lebesgue's Monotone Convergence} theorem, we have
$\mathbb{E}\left[\sup_{n\ge 1}\hat{g}(\theta_{n})\right] \leq  \mathcal{O}(1) $
which implies
\[\mathbb{E}\left[\sup_{n\ge 1}{g}(\theta_{n})\right] \leq  \mathcal{O}(1).\]
\end{proof}



\subsection{The Proof of Theorem \ref{convergence_1.0'}} \label{sec:proof:thm1:rmsprop}
First, we re-write the RMSProp update rule in \cref{RMSProp} to a form of a standard stochastic approximation iteration
\begin{align}\label{SA:rmsprop}
x_{n+1} = x_{n} - \gamma_{n}(g(x_{n})+U_{n}),
\end{align}
where
\[x_{n}:=(\theta_{n},v_{n})^{\top},\ \ \gamma_{n}:=\alpha_{n},\] and
\begin{align*}
    g(x_{n}):=\begin{pmatrix}
\frac{1}{\sqrt{v_{n}}+\epsilon}\circ \nabla g(\theta_{n}) \\
0\end{pmatrix},\ \ U_{n}:=\begin{pmatrix}
\frac{1}{\sqrt{v_{n}}+\epsilon}\circ( \nabla g(\theta_{n},\xi_{n})-\nabla g(\theta_{n}) )\\\frac{1}{\alpha_{n}}(v_{n+1}-v_{n})
\end{pmatrix}.
\end{align*}
Next, we verify that the two conditions in Proposition \ref{SA_p} hold. In fact, based on \cref{bound''} and the coercivity (\cref{extra}~\ref{extra:i1}), we can prove the stability of the iteration sequence $x_n$, which implies that \cref{pros:a1} holds. To verify that \cref{pros:a2} holds, we examine the following term for any $ n\in\mathbb{N}_{+}$
\begin{align*}
    \sup_{m(nT)\le k\le m((n+1)T)}\left\|\sum_{t=m(nT)}^{k}\gamma_{t}U_{t}\right\|&\le  \underbrace{\sup_{m(nT)\le k\le m((n+1)T)}\left\|\sum_{t=m(nT)}^{k}\frac{\alpha_{t}}{\sqrt{v_{t}}+\epsilon}\circ \left(\nabla g(\theta_{t},\xi_{t})-\nabla g(\theta_{t})\right)\right\|}_{B_{n,1}}\\&\quad +\underbrace{\sup_{m(nT)\le t\le k}\left\|v_{k}-v_{m(nT)}\right\|}_{B_{n,2}}.
\end{align*}
First, combining \cref{convergence_v} that \(\{v_{n}\}_{n \geq 1}\) converges almost surely and the \emph{Cauchy's Convergence} principle, we conclude that \(\limsup_{n\rightarrow+\infty}B_{n,2}=\lim_{n\rightarrow+\infty}B_{n,2}=0\ \ \text{a.s.}\)
Then, we adopt a divide-and-conquer strategy and decompose \(B_{n,1}\) by \(B_{n,1,1}\) and \(B_{n,1,2}\) as follows
\begin{align*}
B_{n,1}&\le \underbrace{\sup_{m(nT)\le k\le m((n+1)T)}\left\|\sum_{t=m(nT)}^{k}\sum_{i=1}^{d}\frac{\alpha_{t}\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^2<D_{0}]}}{\sqrt{v_{t},i}+\epsilon}\cdot\left(\nabla_{i} g(\theta_{t},\xi_{t})-\nabla_{i} g(\theta_{t})\right)\right\|}_{B_{n,1,1}}\\&\quad +\underbrace{\sup_{m(nT)\le k\le m((n+1)T)}\left\|\sum_{t=m(nT)}^{k}\sum_{i=1}^{d}\frac{\alpha_{t}\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^2 \geq D_0]}}{\sqrt{v_{t},i}+\epsilon}\cdot\left(\nabla_{i} g(\theta_{t},\xi_{t})-\nabla_{i} g(\theta_{t})\right)\right\|}_{B_{n,1,2}}.
\end{align*}
We first investigate $\mathbb{E}[B_{n,1,1}^{3}]$ and achieve that by applying \emph{Burkholder's inequality}
\begin{align*}
 \mathbb{E}[B_{n,1,1}^{3}]&\le \mathcal{O}(1)\cdot\sum_{t=m(nT)}^{m((n+1)T)}\mathbb{E}\left[\left(\sum_{i=1}^{d}\frac{\alpha_{t}\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^2<D_{0}]}}{\sqrt{v_{t},i}+\epsilon}\cdot\left|\nabla_{i} g(\theta_{t},\xi_{t})-\nabla_{i} g(\theta_{t})\right|\right)^{3}\right] \\&\le \mathcal{O}(1)\cdot\frac{d^{2}}{\epsilon^{3}}\sum_{t=m(nT)}^{m((n+1)T)}\left(\sum_{i=1}^{d}\mathbb{E}\left[{\alpha_{t}^3\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^2<D_{0}]}}\cdot\left|\nabla_{i} g(\theta_{t},\xi_{t})-\nabla_{i} g(\theta_{t})\right|^{3}\right]  \right) \\& \le\mathcal{O}(1)\cdot \frac{4d^{3}(D_{0}^{3/2}+D_{1}^{3/2})}{\epsilon^{3}}\sum_{t=m(nT)}^{m((n+1)T)}\alpha_{t}^{3},
\end{align*}
where $\sqrt{v_{t,i}} + \epsilon > \epsilon$ for all $t \geq 1$ and when $(\nabla_{i}g(\theta_{t}))^2<D_{0}$ we have $(\nabla_{i}g(\theta_{t}; \xi_t))^2<D_{1}$ a.s. (\cref{coordinate}~\ref{coordinate_i_2}).
We set $\alpha_t = O(1/\sqrt{t})$ and conclude $\sum_{n=1}^{+\infty}\mathbb{E}[B_{n,1,1}^{3}]<+\infty $.
By the \emph{Lebesgue's Monotone Convergence} theorem, we have
$ \sum_{n=1}^{+\infty}B_{n,1,1}^{3}<+\infty\ \ \text{a.s.},$ which implies that
\begin{align}\label{dasdwqe}
\limsup_{n\rightarrow+\infty}B_{n,1,1}=0\ \ \text{a.s.}
\end{align}
To examine $B_{n,1,2}$, we investigate $\mathbb{E}[B_{n,1,2}^{2}].$ Applying \emph{Burkholder's inequality} and using $\eta_{t,i} = \alpha_t / \sqrt{v_{t,i}+\epsilon} \leq \eta_{t-1,i}$ and coordinate the affine noise variance condition when $(\nabla_{i}g(\theta_{t}))^2\ge D_{0}$, we have
\begin{align*}
    \mathbb{E}[B_{n,1,2}^{2}]&\le \mathcal{O}(1)\cdot\sum_{t=m(nT)}^{m((n+1)T)}\mathbb{E}\left[\left(\sum_{i=1}^{d}\frac{\alpha_{t-1}\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^2\ge D_{0}]}}{\sqrt{v_{t-1},i}+\epsilon}\cdot\left|\nabla_{i} g(\theta_{t},\xi_{t})-\nabla_{i} g(\theta_{t})\right|\right)^{2}\right] \\&\le \mathcal{O}(1)\cdot \frac{d}{\epsilon}\left(\sigma_{0}+\frac{\sigma_{1}}{D_{0}}\right)\sum_{t=m(nT)}^{m((n+1)T)}\mathbb{E}\left[{\frac{1}{\sqrt{t-1}}}\cdot\sum_{i=1}^{d}\frac{1}{\sqrt{v_{t-1,i}}+\epsilon}\left|\nabla_{i} g(\theta_{t})\right|^{2}\right] \\&\le\mathcal{O}\left(\sum_{t=m(nT)}^{m((n+1)T)}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\zeta_{i}(t)}{\sqrt{t-1}}\right]\right) \le\mathcal{O}\left(\sum_{t=m(nT)}^{m((n+1)T)}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\zeta_{i}(t)}{\sqrt{t}}\right]\right).
\end{align*}
Using \cref{RMSProp_0} with \(\delta = 1/2\), we have  $ \sum_{n=1}^{+\infty}\mathbb{E}[B_{n,1,2}^{2}]<+\infty. $
By the \emph{Lebesgue's Monotone Convergence} theorem, we conclude that:
$\sum_{n=1}^{+\infty}B_{n,1,2}^{2}<+\infty\ \ \text{a.s.},
$ which implies that
\begin{align*}
\limsup_{n\rightarrow+\infty}B_{n,1,2}=0\ \ \text{a.s.}
\end{align*}
We combine the above result with \cref{dasdwqe} and get that
$\limsup_{n\rightarrow+\infty}B_{n,1}=0\ \ \text{a.s.} $ Then, because $\limsup_{n\rightarrow+\infty}B_{n,2}=0\ \ \text{a.s.} $, we conclude that \cref{pros:a2} in \cref{SA_p} is satisfied. Moreover, by applying \cref{extra}~\ref{extra:i2},  \cref{pros:a3} in \cref{SA_p} is also satisfied. Thus, using the statement of \cref{SA_p}, we conclude the almost sure convergence of RMSProp, as we desired.

According to  \cref{RMSProp_0}, for any $0<\delta\le 1/2,$ we have 
\begin{align*}
\sum_{t=1}^{T}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\zeta_{i}(t)}{t^{\delta}}\right]=\mathcal{O}\left(\frac{1}{\delta}\right) .  
\end{align*}
Applying the \emph{Lebesgue's Monotone Convergence} theorem, we have
\begin{align*}
\sum_{t=1}^{T}\sum_{i=1}^{d}\frac{\zeta_{i}(t)}{t^{\delta}}<+\infty\ \ \text{a.s.}.  \end{align*}
Recalling that $\zeta_{i}(t) = (\nabla_i g(\theta_t))^2 \eta_{t-1,i} \geq (\nabla_i g(\theta_t))^2 \eta_{t,i}$ (by \cref{property_0}) and $\eta_{t,i} = \alpha_t / (\sqrt{v_{t,i}} + \epsilon)$, we have
\begin{align*}
\sum_{t=1}^{T}\sum_{i=1}^{d}\frac{\zeta_{i}(t)}{t^{\delta}} \geq  \sum_{t=1}^{T}\sum_{i=1}^{d}\frac{1}{t^{\frac{1}{2}+\delta}}\frac{(\nabla_{i}g(\theta_{t}))^{2}}{\sqrt{v_{t,i}}+\epsilon}\mathop{\ge}^{\text{\cref{bounded_v}}}\mathcal{O}\left( \sum_{t=1}^{T}\sum_{i=1}^{d}\frac{(\nabla_{i}g(\theta_{t}))^{2}}{t^{\frac{1}{2}+\delta}\ln(t+1)}\right)  ,
\end{align*}
where by \text{\cref{bounded_v}}, we have $v_{t,i} \leq \Sigma_{v_t} \leq \sup_{t} \Sigma_{v_t} \leq \mathcal{O}(\ln^2(t+1)) $.

Recalling the recursive formula for \(v_t\), we have
\begin{align*}
   v_{t+1,i}\le v_{t,i}+\frac{1}{t+1}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} = v_{t,i}+\frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}<D_{0}]}}{t+1}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} +\frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}}{t+1}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}.
\end{align*}
Next, we examine the sum of the two series
\begin{align*}
 \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}<D_{0}]}}{(t+1)^{2}}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{4} |\mathscr{F}_{t-1}\right],\ \ \text{and}\ \  \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}}{t+1}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}|\mathscr{F}_{t-1}\right] .
\end{align*}
For the first series, based on \cref{coordinate}~\ref{coordinate_i_2}, it concludes
\begin{align*}
 \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}<D_{0}]}}{(t+1)^{2}}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{4} |\mathscr{F}_{t-1}\right]&<D_{1}^{2}  \sum_{t=1}^{+\infty}  \frac{1}{(t+1)^{2}}<+\infty\ \ \text{a.s.}
\end{align*}
We apply the coordinate-wise affine noise variance condition when $\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}$  and achieve that $\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} |\mathscr{F}_{t-1}\right] \leq \left(\sigma_0 \nabla_{i}g(\theta_{t}))^{2}  + \sigma_1 \right) \leq (\sigma_{0}+\frac{\sigma_{1}}{D_{0}})\nabla_{i}g(\theta_{t}))^{2}$ for any $\ i$. For the second series, 
\begin{align*}
 \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}}{t+1}\mathbb{E}\left[(\nabla_{i}g(\theta_{t},\xi_{t}))^{2} |\mathscr{F}_{t-1}\right]&<\left(\sigma_{0}+\frac{\sigma_{1}}{D_{0}}\right)  \sum_{t=1}^{+\infty}  \frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}(\nabla_{i}g(\theta_{t}))^{2}}{(t+1)^{2}}\\& \leq \mathcal{O}\left(\sum_{t=1}^{+\infty}  \sum_{i=1}^{d}\frac{\mathbb{I}_{[(\nabla_{i}g(\theta_{t}))^{2}\ge D_{0}]}(\nabla_{i}g(\theta_{t}))^{2}}{t\ln(t+1)}\right)\\&\mathop{<}^{\text{ \cref{RMSProp_9} with $\delta=1/2$}}+\infty \ \ \text{a.s.}.
\end{align*}
According to the martingale convergence theorem, we have \(\{v_{t,i}\}_{t \geq 1}\) converges almost surely. Repeating the above procedure for each component \(i\), we conclude that all coordinate components converge almost surely which implies that \(\{v_{n}\}_{n \geq 1}\) converges almost surely.

(of \cref{bound''}) 
First, we define \(\Delta_{0} := \max\{C_{0}, 2\hat{g}(\theta_{1}), \hat{C}_{g}\}\). Based on the value of \(\hat{g}(\theta_{n})\) with respect to \(\Delta_{0}\), we define the following stopping time sequence $\{\tau_{n}\}_{n\ge 1}$
\begin{align}\label{stopping_time'}
&\tau_{1}:=\min\{k\ge 1:\hat{g}(\theta_{k})>\Delta_0\},\ \tau_{2}:=\min\{k\ge \tau_{1}: \hat{g}(\theta_{k})\le  \Delta_0\ \text{or}\ \hat{g}(\theta_{k})>2\Delta_0\},\notag\\&\tau_{3}:=\min\{k\ge \tau_{2}:\hat{g}(\theta_{k})\le \Delta_0\},...,
\notag\\&\tau_{3j-2}:=\min\{k> \tau_{3j-3}:\hat{g}(\theta_{k})>\Delta_0\},\ \tau_{3j-1}:=\min\{k\ge \tau_{3j-2}:\hat{g}(\theta_{k})\le  \Delta_0\ \text{or}\ \hat{g}(\theta_{k})>2\Delta_0\},\notag\\&\tau_{3j}:=\min\{k\ge  \tau_{3j-1}:\hat{g}(\theta_{k})\le  \Delta_0\}.
\end{align}
By the definition of \(\Delta_{0}\), we have \(\Delta_{0} > \hat{g}(\theta_{1})\), which asserts \(\tau_{1} > 1\). Since \(\Delta_{0} > C_{0}\), for any \(j\), we have \(\hat{g}(\theta_{\tau_{3j-2}}) < \Delta_{0} + \frac{\Delta_{0}}{2} < 2\Delta_{0}\), which asserts \(\tau_{3j-1} > \tau_{3j-2}\). For any \(T\) and \(n\), we define the truncated stopping time \(\tau_{n,T} := \tau_{n} \wedge T\). Then, based on the segments by the stopping time $\tau_{n, T}$, we estimate \(\mathbb{E}\left[\sup_{1 \leq n < T} \hat{g}(\theta_{n})\right]\) as follows.
\begin{align}\label{RMSprop_7}
   \mathbb{E}\left[\sup_{1\le n<T}\hat{g}(\theta_{n})\right]&\le \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-2,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right] +\mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j,T}\le n<\tau_{3j+1,T}}\hat{g}(\theta_{n})\right)\right]\notag\\&\le \Delta_{0}+ \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-2,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]\notag\\&\le \Delta_{0}+  \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-2,T}\le n<\tau_{3j-1,T}}\hat{g}(\theta_{n})\right)\right]+ \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]\notag\\&\le 3\Delta_{0}+ \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right].
\end{align}
Next, we proceed to estimate \(\mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]\).
\begin{align}\label{RMSprop_5}
 \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\hat{g}(\theta_{n})\right)\right]& \mathop{\le}^{\text{\cref{lem:adj:ghat''}}}  3\Delta_{0}+  \mathbb{E}\left[\sup_{j\ge 1}\left(\sup_{\tau_{3j-1,T}\le n<\tau_{3j,T}}\left(\hat{g}(\theta_{n})-\hat{g}(\theta_{\tau_{3j-1,T}})\right)\right)\right]\notag\\&\le 3\Delta_{0}+  \mathbb{E}\left[\sup_{j\ge 1}\left(\sum_{t=\tau_{3j-1,T}}^{\tau_{3j,T}-1}\left|\hat{g}(\theta_{t+1})-\hat{g}(\theta_{t})\right|\right)\right]\notag\\& \mathop{\le}^{(a)} \mathcal{O}(1)+\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1,T}}^{\tau_{3j,T}-1}\sum_{i=1}^{d}\zeta_{i}(t)\right]\right),
\end{align}
where we follow the same procedure as \cref{inqu:diff:g:tau2} to derive the inequality $(a)$. The constant hidden within the \(\mathcal{O}\) notation is independent of \(T\). Applying the sufficient descent inequality in \cref{sufficient:lem'}, the last term of RHS of \cref{RMSprop_5} is bounded by
\begin{align}\label{RMSprop_6}
\quad & \leq \sum_{j=1}^{+\infty}\mathbb{E}\left[\hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j,T}})\right]+\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1},T}^{\tau_{3j,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right] \notag \\
& \quad +\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1},T}^{\tau_{3j,T}-1}M_{t}\right]\notag\\&=\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\right)+\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1},T}^{\tau_{3j,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]\right)+0\notag\\&\mathop{\le}^{(a)}\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\right)+\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\sum_{t=\tau_{3j-1,T}}^{\tau_{3j,T}-1}\sum_{i=1}^{d}\frac{\zeta_{i}(t)}{\sqrt{t}}\right]\right)\notag\\&\mathop{\le}^{\text{ \cref{RMSProp_0}}}\mathcal{O}\left(\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\right)+\mathcal{O}\left(1\right).   
\end{align}

Similar to the proof of ~\cref{lem:psi:i1}, the following inclusions of the events hold
\begin{align*}
\{\tau_{3j-1,T}<\tau_{3j,T}\}&\subset \{\hat{g}(\theta_{3i-1,T})>2\Delta_{0}\}\subset\left\{\frac{\Delta_{0}}{2}\le \hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j-2,T}})\right\}.
\end{align*}
To estimate \(\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\), we evaluate the probability of the event \(W=\left\{\frac{\Delta_{0}}{2}\le \hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j-2,T}})\right\}.\) Note that when the event $W$ occurs 
\begin{align*}
    \frac{\Delta_{0}}{2}&\le \hat{g}(\theta_{\tau_{3j-1,T}})-\hat{g}(\theta_{\tau_{3j-2,T}}) \mathop{\le}^{\text{ \cref{sufficient:lem'}}}\left({ L}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}+\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\\&\mathop{\le}^{\text{\emph{AM-GM} inequality}}\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}+\frac{\Delta_{0}}{4}+\frac{1}{\Delta_{0}}\left(\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\right)^{2},
\end{align*}
which implies that the following inequality holds
\begin{align}\label{RMSprop_2}
    \frac{\Delta_{0}}{4}&\le\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}+\frac{1}{\Delta_{0}}\left(\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\right)^{2}.
\end{align}
Combining the above derivations, when the event \(\{\tau_{3j-1,T}<\tau_{3j,T}\}\) occurs, the event \(\{\text{\cref{RMSprop_2} holds}\}\) also occurs, which implies that
\begin{align}\label{RMSProp_2}
&\quad \mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right] \notag \\
& \le\mathbb{P}\left[\{\text{\cref{RMSprop_2} holds}\}\right]\notag\\&\mathop{\le}^{\text{\emph{Markov's} inequality}}\frac{4}{\Delta_{0}}\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]+\frac{4}{\Delta_{0}^{2}}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M_{t}\right]^{2}\notag\\&\mathop{\le}^{\text{\emph{Doob's Stopped} theorem}}\frac{4}{\Delta_{0}}\left(\frac{ L}{2}+\frac{(2\sigma_{0}+1) L^{2}}{\sqrt{v}}\right)\underbrace{\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]}_{A_{j,1}}+\frac{4}{\Delta_{0}^{2}}\underbrace{\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}M^{2}_{t}\right]}_{A_{j,2}}.
\end{align}
For \(A_{j,1}\), we further estimate it as follows.
\begin{align*}
A_{j,1}&=\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}\right]\mathop{=}^{\text{\emph{Doob's Stopped} theorem}}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\mathbb{E}\left[\|\eta_t\circ \nabla g(\theta_{t},\xi_{t})\|^{2}|\mathscr{F}_{t-1}\right]\right]\\&\le\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\mathbb{E}\left[\eta^{2}_{{t},i}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}|\mathscr{F}_{t-1}\right]\right] \notag \\
& \mathop{\le}^{\eta_{t,i}\le \frac{1}{\epsilon\sqrt{t}}}\frac{1}{\epsilon}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\eta_{t,i}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}}{\sqrt{t}}\bigg|\mathscr{F}_{t-1}\right]\right]\\&\mathop{\le}^{\text{\cref{property_0}}}\frac{1}{\epsilon}\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\mathbb{E}\left[\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t},\xi_{t}))^{2}\bigg|\mathscr{F}_{t-1}\right]\right] \notag \\

&\mathop{\le}^{(a)}\frac{1}{\epsilon}\left(\sigma_{0}+\frac{\sigma_{1}}{\eta}\right)\mathbb{E}\left[\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right].
\end{align*}
In \((a)\), if the stopping times \(\tau_{3j-2,T} = \tau_{3j-1,T}\), we define the sum \(\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1} = 0\), so it holds trivially. When \(\tau_{3j-2,T} < \tau_{3j-1,T}\), we know $\hat{g}(\theta_t) \in (\Delta_0, 2\Delta_0]$ where $\Delta_0 > \hat{C}_g$ for any \(t \in [\tau_{3j-2,T}, \tau_{3j-1,T})\). By \cref{{dsad}}, we have \((\nabla_{i}g(\theta_{t}))^{2} > \eta\) for any \(t \in [\tau_{3j-2,T}, \tau_{3j-1,T})\)  and $i \in [d]$. By the coordinated affine noise variance condition, we have \[\mathbb{E}\left[(\nabla_{i}g(\theta_{t}, \xi_{t}))^{2} \mid \mathscr{F}_{t-1}\right] \leq \sigma_{0}(\nabla_{i}g(\theta_{t}))^{2} + \sigma_{1} \leq \left(\sigma_{0} + \frac{\sigma_{1}}{\eta}\right)(\nabla_{i}g(\theta_{t}))^{2}.\]
We further show that $ \sum_{j=1}^{+\infty}A_{j,1}$ is uniformly bounded. In fact,
\begin{align*}
    \sum_{j=1}^{+\infty}A_{j,1}&\le \frac{1}{\epsilon}\left(\sigma_{0}+\frac{\sigma_{1}}{\eta}\right)\mathbb{E}\left[\sum_{j=1}^{+\infty}\sum_{t=\tau_{3j-2,T}}^{\tau_{3j-1,T}-1}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right] \leq \mathcal{O}\left(\sum_{t=1}^{+\infty}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right)\\&\mathop{\le}^{\text{\cref{RMSProp_0} with $\delta=1/2$}}\mathcal{O}(1).
\end{align*}
Then, following the same procedure as $A_{j,1}$ to estimate \(A_{j,2}\), we obtain that
\begin{align*}
 \sum_{j=1}^{+\infty}A_{j,2}\le \mathcal{O}\left(\sum_{t=1}^{+\infty}\sum_{i=1}^{d}\frac{\eta_{{t-1},i}}{\sqrt{t}}(\nabla_{i}g(\theta_{t}))^{2}\right)\mathop{\le}^{\text{\cref{RMSProp_0} with $\delta=1/2$}}\mathcal{O}(1).  
\end{align*}
According to \cref{RMSprop_2}, combining the estimates for $A_{j,1}$ and $A_{j,2}$ gives
\begin{align*}
\sum_{j=1}^{+\infty}\mathbb{E}\left[\mathbb{I}_{\tau_{3j-1,T}<\tau_{3j,T}}\right]\le \mathcal{O}\left(\sum_{j=1}^{+\infty}A_{j,1}\right)+\mathcal{O}\left(\sum_{j=1}^{+\infty}A_{j,2}\right)\le \mathcal{O}(1).
\end{align*}
Substituting the above estimate into \cref{RMSprop_6}, and then into \cref{RMSprop_5} and \cref{RMSprop_7}, we obtain
\begin{align*}
\mathbb{E}\left[\sup_{1\le n<T}\hat{g}(\theta_{n})\right]  \le \mathcal{O}(1).
\end{align*}
where the constant hidden in \(\mathcal{O}\) is independent of \(T\). Taking \(T \to +\infty\) and applying the \emph{Lebesgue's Monotone Convergence} theorem, we have
$\mathbb{E}\left[\sup_{n\ge 1}\hat{g}(\theta_{n})\right] \leq  \mathcal{O}(1) $
which implies
\[\mathbb{E}\left[\sup_{n\ge 1}{g}(\theta_{n})\right] \leq  \mathcal{O}(1).\]
